// 自动生成：npm run quran:all（scripts/fetch-quran-all.mjs）。请勿手改经文。
export default {"52":["Клянусь горой!","Клянусь Писанием, начертанным","на развернутой нежной коже!","Клянусь домом наполненным (храмом на седьмом небе)!","Клянусь кровлей возведенной!","Клянусь морем разожженным (или переполненным; или опустевшим; или перемешанным; или удерживаемым)!","Наказание твоего Господа непременно наступит,","и ничто не отвратит его.","В тот день небо содрогнется от колебаний,","а горы придут в движение.","Горе в тот день тем, кто считает истину ложью,","кто забавляется, предаваясь празднословию.","В тот день они будут нещадно ввергнуты в огонь Геенны.","Это - тот самый Огонь, который вы считали ложью.","Неужели это колдовство? Или же вы не видите?","Горите в нем! Вам все равно, будете вы терпеть или не станете проявлять терпения. Вам воздается только за то, что вы совершали.","Воистину, богобоязненные пребудут в Райских садах и блаженстве.","Они будут радоваться тому, чем их одарит их Господь. Господь их уберег их от мучений в Аду.","Ешьте и пейте во здравие за то, что вы совершали!","Они будут, прислонившись, возлежать на ложах, выстроенных в ряд, и Мы сочетаем их с черноокими, большеглазыми гуриями.","Мы воссоединим верующих с их потомками, которые последовали за ними в вере, и нисколько не умалим их деяний. Каждый человек является заложником того, что он приобрел.","Мы наделим их фруктами и мясом таким, какое они пожелают.","Они будут передавать друг другу чашу с вином, которое не принесет ни празднословия, ни греха.","Их будут обходить их юные слуги, подобные сокрытому жемчугу.","Они будут расспрашивать друг друга.","Они скажут: «Прежде, находясь в кругу своих семей, мы трепетали от страха.","Аллах же оказал нам милость и уберег нас от мучений знойного ветра (или мучений в Аду).","Мы взывали к Нему прежде. Воистину, Он - Добродетельный, Милосердный».","Напоминай же! По милости своего Господа ты не являешься ни прорицателем, ни одержимым.","Или же они говорят: «Он - поэт! Давайте же подождем, пока время не разберется с ним».","Скажи: «Ждите, и я подожду вместе с вами».","Неужели умы повелевают им такое? Или же они являются людьми преступными?","Или же они говорят: «Он выдумал его!». О нет! Просто они не веруют.","Пусть приведут подобное ему (Корану) повествование, если они говорят правду.","Неужели они были сотворены сами по себе (или просто так)? Или же они сами являются творцами?","Или же это они сотворили небеса и землю? О нет! Просто они лишены убежденности.","Неужели у них находятся сокровищницы твоего Господа? Или же они сами являются владыками?","Или же у них есть лестница, на которой они подслушивают разговоры ангелов? Пусть тот из них, кто подслушивал, приведет ясное доказательство.","Неужели у Него - дочери, а у вас - сыновья?","Или же ты просишь у них вознаграждения, и они обременены обязательствами?","Или же они владеют сокровенным и записывают его?","Или же они желают замыслить козни? Но ведь неверующие сами станут жертвой козней.","Или же у них есть другой бог наряду с Аллахом? Аллах пречист и далек от тех, кого они приобщают в сотоварищи!","Даже если они увидят куски неба падающими, они скажут: «Это скопились облака!».","Оставь же их, пока они не встретят тот день их, когда их постигнет погибель.","В тот день их козни не принесут им никакой пользы, и никто не поможет им.","Воистину, беззаконникам уготованы мучения и перед этим, но большинство их не знает этого.","Потерпи же до решения твоего Господа, ведь ты - у Нас на Глазах. Прославляй хвалой своего Господа, когда поднимаешься ото сна.","Среди ночи восхваляй Его и при исчезновении звезд."],"53":["Клянусь звездой, когда она падает (или частью Корана, когда она нисходит)!","Не заблудился ваш товарищ и не сошел с пути.","Он не говорит по прихоти.","Это - всего лишь внушаемое ему откровение.","Научил его обладающий могучей силой","и прекрасным сложением (или благоразумием). Он вознесся (или выпрямился)","на наивысшем горизонте.","Потом он приблизился и спустился.","Он находился от него (Джибрил от Мухаммада или Мухаммад от Аллаха) на расстоянии двух луков или даже ближе.","Он внушил Его рабу откровение,","и сердце не солгало о том, что он увидел.","Неужели вы будете препираться с ним о том, что он увидел?","Он уже видел его другое нисхождение","у Лотоса крайнего предела,","возле которого находится Сад пристанища.","Тогда Лотос покрыло то, что покрыло (золотая саранча, или группы ангелов, или повеление Аллаха).","Его же взор не уклонился в сторону и не излишествовал,","и он увидел величайшие из знамений своего Господа.","Не видели ли вы аль-Лат и аль-Уззу,","и еще третью - Манат?","Неужели у вас - потомки мужского пола, а у Него - женского?","Это было бы несправедливым распределением.","Они - всего лишь имена, которыми нарекли их вы и ваши отцы, относительно которых Аллах не ниспослал никакого доказательства. Они следуют лишь предположениям и тому, чего желают души, хотя верное руководство от их Господа уже явилось к ним.","Или же для человека уготовано то, чего он желает?","Аллаху принадлежит Последняя жизнь и жизнь первая.","Сколько же на небесах ангелов, заступничество которых не принесет никакой пользы, пока Аллах не позволит заступиться за тех, за кого Он пожелает и кем Он доволен!","Воистину, те, которые не веруют в Последнюю жизнь, называют ангелов женщинами.","У них нет об этом никакого знания. Они следуют лишь предположениям, хотя предположения не могут заменить истину.","Отвернись же от того, кто отвернулся от Нашего Напоминания и не пожелал ничего, кроме мирской жизни.","Таков предел их познаний. Воистину, твоему Господу лучше знать тех, кто сбился с Его пути, и лучше знать тех, кто последовал прямым путем.","Аллаху принадлежит то, что на небесах, и то, что на земле, дабы Он воздал злодеям за то, что они совершили, и воздал творившим добро Наилучшим (Раем).","Они избегают великих грехов и мерзостей, кроме мелких и немногочисленных проступков. Воистину, твой Господь обладает необъятным прощением. Ему было лучше знать о вас, когда Он сотворил вас из земли и когда вы были зародышами в утробах ваших матерей. Не восхваляйте самих себя, ибо Ему лучше знать тех, кто богобоязнен.","Видел ли ты того, кто отвернулся,","дал мало и прекратил давать вовсе?","Разве он обладает таким знанием о сокровенном, что он видит его?","Разве ему не поведали о том, что было в свитках Мусы (Моисея)","и Ибрахима (Авраама), который выполнил повеления Аллаха полностью?","Ни одна душа не понесет чужого бремени.","Человек получит только то, к чему он стремился.","Его устремления будут увидены,","а затем он получит воздаяние сполна.","К твоему Господу предстоит конечный исход (или твоему Господу принадлежит конечный предел).","Он заставляет смеяться и плакать.","Он умерщвляет и оживляет.","Он сотворил пару - мужчину и женщину (или самца и самку) -","из капли, которая извергается.","На Нем лежит сотворение в другой раз.","Он избавляет от нужды (или дарует богатство) и наделяет собственностью (или удовлетворяет).","Он - Господь Сириуса.","Он погубил первых адитов,","ничего не оставил от самудян,","а еще раньше погубил народ Нуха (Ноя). Воистину, они были еще более несправедливы и непокорны.","Он низверг опрокинутые селения (селения народа Лута),","которые покрыло то, что покрыло.","В каких же милостях твоего Господа ты сомневаешься?","Этот предостерегающий увещеватель такой же, как и первые предостерегающие увещеватели.","Приближающееся (День воскресения) приблизилось,","и никто, кроме Аллаха, не способен отвратить его.","Неужели вы удивляетесь этому повествованию,","смеетесь, а не плачете,","и забавляетесь (или поете; или надменно задираете головы)?","Падите же ниц перед Аллахом и поклоняйтесь!"],"54":["Приблизился Час, и раскололся месяц.","Когда они видят знамение, то отворачиваются и говорят: «Это - преходящее (или крепкое; или лживое) колдовство!».","Они сочли лжецами посланников и потакали своим желаниям, но каждый поступок утвердится (творения получат вознаграждение за добро и наказание за зло).","До них уже дошли известия, которые удерживали от неверия.","Это является совершенной мудростью, но какую пользу приносят предостережения (или предостережения не принесли им никакой пользы)?","Отвернись же от них. В тот день, когда глашатай призовет к неприятной вещи,","они с униженными взорами выйдут из могил, словно рассеянная саранча.","Они устремятся к глашатаю, и неверующие скажут: «Это - Тяжкий день!».","До них счел лжецами посланников народ Нуха (Ноя). Они сочли лжецом Нашего раба и сказали: «Он - одержимый!». Они ругали его и угрожали ему.","Тогда он воззвал к своему Господу: «Меня одолели. Помоги же мне!».","Мы открыли врата неба, откуда стала изливаться вода,","и разверзли землю, из которой забили ключи. Воды небес и земли слились для дела, которое было предопределено.","Мы понесли его в ковчеге из досок и гвоздей.","Ковчег поплыл у Нас на Глазах в воздаяние тому, в кого не уверовали (или тем, которые не уверовали).","Мы оставили его (корабль или рассказ о Нухе) в качестве знамения. Но есть ли среди вас вспоминающие?","Какими же были мучения от Меня и предостережения Мои!","Мы облегчили Коран для поминания. Но есть ли среди вас вспоминающие?","Адиты сочли лжецами посланников. Какими же были мучения от Меня и предостережения Мои!","Мы наслали на них морозный (или завывающий) ветер в день, злосчастье которого продолжалось.","Он вырывал людей, словно стволы выкорчеванных финиковых пальм.","Какими же были мучения от Меня и предостережения Мои!","Мы облегчили Коран для поминания. Но есть ли среди вас вспоминающие?","Самудяне сочли ложью предостережения.","Они сказали: «Неужели мы последуем за одним из нас? В этом случае мы окажемся в заблуждении и будем страдать (или отдалимся от истины).","Неужели среди всех нас напоминание ниспослано только ему одному? О нет! Он - надменный лжец».","Завтра они узнают, кто является надменным лжецом!","Аллах сказал их пророку: «Мы посылаем верблюдицу для того, чтобы испытать их. Подожди же и будь терпелив.","Сообщи им, что вода поделена между ними и верблюдицей. Пусть же они приходят попить каждый раз в отведенное для них время».","Они позвали своего товарища, и тот схватил верблюдицу и перерезал ей поджилки.","Какими же были мучения от Меня и предостережения Мои!","Воистину, Мы наслали на них всего лишь один вопль, и они уподобились сену хозяина загона.","Мы облегчили Коран для поминания. Но есть ли среди вас вспоминающие?","Народ Лута (Лота) счел ложью предостережения.","Мы наслали на них ураган с камнями, и только семью Лута (Лота) Мы спасли перед рассветом","по милости от Нас. Так Мы воздаем тем, кто благодарен.","Он предостерег их от Нашей Хватки, но они усомнились в его предостережениях.","Они настойчиво требовали от него его гостей, и тогда Мы лишили их зрения. Вкусите же мучения от Меня и предостережения Мои!","На утро их постигли неотвратимые мучения.","Вкусите же мучения от Меня и предостережения Мои!","Мы облегчили Коран для поминания. Но есть ли среди вас вспоминающие?","Предостережения также явились к роду Фараона.","Они сочли ложью все Наши знамения, и Мы схватили их Хваткой Могущественного, Всемогущего.","Разве ваши неверующие лучше тех? Или же у вас есть неприкосновенность, упомянутая в Писаниях?","Или же они говорят: «Мы являемся победоносной группой».","Эта группа будет разбита, и они обратятся вспять!","Час является назначенным для них сроком, и Час этот - самый тяжкий, самый горький.","Воистину, грешники сбились с пути и страдают (или отдалились от истины).","В тот день их ничком поволокут в Огонь: «Вкусите прикосновение Преисподней!».","Воистину, Мы сотворили каждую вещь согласно предопределению.","Мы повелеваем только один раз, и повеление исполняется в мгновение ока.","Мы уже погубили подобных вам. Но есть ли среди вас вспоминающие?","Все, что они совершили, есть в книгах деяний.","Все малое и великое уже начертано.","Воистину, богобоязненные пребудут в Райских садах и среди рек","на седалище истины возле Всемогущего Властелина."],"55":["Милостивый","научил Корану,","создал человека","и научил его изъясняться.","Солнце и луна движутся согласно рассчитанному порядку.","Травы (или звезды) и деревья совершают поклоны.","Он возвысил небо и установил весы,","чтобы вы не преступали границы дозволенного на весах.","Взвешивайте беспристрастно и не занижайте вес.","Он установил землю для тварей.","На ней есть фрукты и финиковые пальмы с чашечками (или волокнами),","а также злаки с листьями и травы благоуханные.","Какую же из милостей вашего Господа вы считаете ложью?","Он создал человека из сухой (или звенящей) глины, подобной гончарной,","и создал джиннов из чистого пламени (или из пламени, смешанного с дымом).","Какую же из милостей вашего Господа вы считаете ложью?","Господь обоих востоков и Господь обоих западов!","Какую же из милостей вашего Господа вы считаете ложью?","Он смешал два моря, которые встречаются друг с другом.","Между ними существует преграда, которую они не могут преступить.","Какую же из милостей вашего Господа вы считаете ложью?","Из них обоих вылавливают жемчуг и кораллы.","Какую же из милостей вашего Господа вы считаете ложью?","Ему принадлежат плывущие по морю с поднятыми парусами корабли, подобные горам.","Какую же из милостей вашего Господа вы считаете ложью?","Все на ней (земле) смертны.","Вечен лишь Лик Господа твоего, обладающий величием и великодушием.","Какую же из милостей вашего Господа вы считаете ложью?","Его просят те, кто на небесах и на земле, и каждый день Он занят делом.","Какую же из милостей вашего Господа вы считаете ложью?","Скоро Мы займемся только вами, о два весомых (или обремененных) рода!","Какую же из милостей вашего Господа вы считаете ложью?","О сонмище джиннов и людей! Если вы можете проникнуть за пределы небес и земли, то проникните. Но вы не проникните, не обладая властью (или ясным доводом)!","Какую же из милостей вашего Господа вы считаете ложью?","На вас нашлют зеленое пламя (или пламя без дыма) и расплавленную медь (или дым), и вы не поможете друг другу.","Какую же из милостей вашего Господа вы считаете ложью?","И вот небо разверзнется и станет красным, как кипящее масло (или покрасневшая кожа; или расплавленный свинец).","Какую же из милостей вашего Господа вы считаете ложью?","В тот день ни человек, ни джинн не будет спрошен о его грехе.","Какую же из милостей вашего Господа вы считаете ложью?","Грешников будут узнавать по их признакам, а затем хватать за хохлы и стопы.","Какую же из милостей вашего Господа вы считаете ложью?","Вот Геенна, которую грешники считали ложью.","Они будут ходить между нею и кипящей водой.","Какую же из милостей вашего Господа вы считаете ложью?","Тем же, которые боялись предстать перед своим Господом, уготовано два сада.","Какую же из милостей вашего Господа вы считаете ложью?","В них обоих есть ветви.","Какую же из милостей вашего Господа вы считаете ложью?","В них обоих текут два источника.","Какую же из милостей вашего Господа вы считаете ложью?","В них обоих есть от всех фруктов по паре.","Какую же из милостей вашего Господа вы считаете ложью?","Они будут лежать, прислонившись, на матрацах, выстланных снизу парчой, а свежие плоды этих двух садов будут склоняться низко.","Какую же из милостей вашего Господа вы считаете ложью?","Там будут девы, потупляющие взоры, с которыми прежде не имели близости ни человек, ни джинн.","Какую же из милостей вашего Господа вы считаете ложью?","Они подобны рубинам и кораллам.","Какую же из милостей вашего Господа вы считаете ложью?","Воздают ли за добро иначе, чем добром?","Какую же из милостей вашего Господа вы считаете ложью?","А перед теми двумя есть еще два сада.","Какую же из милостей вашего Господа вы считаете ложью?","Они оба - темно-зеленые.","Какую же из милостей вашего Господа вы считаете ложью?","В них обоих бурлят два источника.","Какую же из милостей вашего Господа вы считаете ложью?","В них обоих есть фрукты, финиковые пальмы, гранаты.","Какую же из милостей вашего Господа вы считаете ложью?","Там есть девы хорошие, прекрасные.","Какую же из милостей вашего Господа вы считаете ложью?","Они - черноокие и большеглазые, удерживаемые в шатрах.","Какую же из милостей вашего Господа вы считаете ложью?","С ними прежде не имели близости ни человек, ни джинн.","Какую же из милостей вашего Господа вы считаете ложью?","Они будут лежать, прислонившись, на зеленых подушках и прекрасных матрацах.","Какую же из милостей вашего Господа вы считаете ложью?","Благословенно имя Господа твоего, Обладающего величием и великодушием!"],"56":["Когда наступит Событие (День воскресения),","никто не сочтет его наступление ложью.","Оно унижает и возвышает.","Когда земля сильно содрогнется,","когда горы раскрошатся на мелкие кусочки,","а затем превратятся в развеянный прах,","вы разделитесь на три группы.","Одни будут по правую сторону. Кто же будет по правую сторону?","Другие же будут по левую сторону. Кто же будет по левую сторону?","И будут опередившие их всех в добре, которые опередят их и в Раю.","Это будут приближенные,","которые пребудут в Садах блаженства.","Многие из них - из первых поколений,","и лишь немногие - из последних.","Они будут лежать на расшитых ложах","друг против друга, прислонившись.","Вечно юные отроки будут обходить их","с чашами, кувшинами и кубками с родниковым напитком (вином),","от которого не болит голова и не теряют рассудок,","с фруктами, которые они выбирают,","и мясом птиц, которое они желают.","Их женами будут черноокие, большеглазые девы,","подобные сокрытым жемчужинам.","Таково воздаяние за то, что они совершали.","Они не услышат там ни празднословия, ни греховных речей,","а только слова: «Мир! Мир!».","И будут те, кто по правую сторону. Кто же будет по правую сторону?","Они пребудут среди лотосов, лишенных шипов,","под бананами (или акациями камеденосными) с висящими рядами плодами,","в распростертой тени,","среди разлитых вод","и многочисленных фруктов,","которые не кончаются и доступны.","Они будут лежать на приподнятых матрацах.","Мы сотворим их в новом облике (совершенными)","и сделаем их девственницами,","любящими и равными по возрасту.","Это - для тех, кто по правую сторону.","Многие из них - из первых поколений,","а многие - из последних.","И будут те, кто по левую сторону. Кто же будет по левую сторону?","Они окажутся под знойным ветром и в кипятке,","в тени черного дыма,","которая не приносит ни прохлады, ни добра.","Прежде они нежились роскошью,","упорствовали в великом грехе","и говорили: «Неужели мы будем воскрешены после того, как мы умрем и станем прахом и костями?","Или же наши праотцы?».","Скажи: «Воистину, как первые, так и последние поколения","будут собраны в определенном месте в известный день.","Тогда вы, о заблудшие, считающие лжецами посланников,","непременно вкусите от дерева заккум.","Вы будете набивать ими животы","и запивать их кипятком,","как пьют больные верблюды, которые не могут спастись от жажды».","Таким для них будет угощение в День воздаяния.","Мы сотворили вас. Почему же вы не признаете воскрешения?","Видели ли вы семя, которое вы извергаете?","Вы создаете его или Мы создаем?","Мы распределили между вами смерть, и ничто не может помешать Нам","заменить вас подобными вам (или изменить ваше обличие) и создать вас такими, какими вы себе и не представляете.","Вы уже знаете о первом сотворении. Почему же вы не помяните назидание?","Видели ли вы то, что вы сеете?","Вы ли заставляете его произрасти или Мы заставляем?","Если Мы пожелаем, то превратим его в труху, и тогда вы останетесь удивленными","и скажите: «Воистину, мы потерпели убыток.","Более того, мы лишились пропитания».","Видели ли вы воду, которую вы пьете?","Вы ли ниспосылаете ее из дождевых туч или Мы ниспосылаем?","Если бы Мы пожелали, то сделали бы ее горькой. Почему же вы неблагодарны?","Видели ли вы огонь, который вы высекаете?","Вы ли создаете деревья для него или Мы создаем?","Мы сделали его напоминанием и предметом пользования для путников.","Прославляй же имя Великого Господа твоего!","Но нет! Клянусь местами заката звезд (или ниспослания частей Корана)!","Если бы вы только знали, что это - клятва великая.","Воистину, это - благородный Коран,","находящийся в Хранимом Писании.","К нему прикасаются только очищенные.","Он ниспослан Господом миров.","Неужели вы не веруете в это повествование (или отворачиваетесь от него)","и делаете ваш удел тем, что считаете ложью истину?","А когда душа подступает к горлу","и вы смотрите на умирающего,","Мы находимся ближе вас к нему, хотя вы не видите этого.","Почему же вы, если вы действительно не получите воздаяние","не вернете ее, если вы говорите правду?","Если он будет одним из приближенных,","то обретет покой (или радость; или милость), удел (или базилик) и Сад блаженства.","Если он будет одним из тех, кто по правую сторону,","то ему скажут: «Мир тебе! Ты являешься одним из тех, кто на правой стороне».","Если же он будет одним из заблудших, считавших лжецами посланников,","то угощением для него будет кипяток,","и он будет гореть в Аду.","Это и есть истина!","Прославляй же имя Господа твоего Великого!"],"57":["Славит Аллаха то, что на небесах и на земле. Он - Могущественный, Мудрый.","Ему принадлежит власть над небесами и землей. Он оживляет и умерщвляет, и Он способен на всякую вещь.","Он - Первый и Последний, Высочайший и Ближайший. Он знает о всякой вещи.","Он - Тот, Кто сотворил небеса и землю за шесть дней, а затем вознесся на Трон (или утвердился на Троне). Он знает то, что проникает в землю, и то, что выходит из нее, и то, что нисходит с неба, и то, что восходит к нему. Он с вами, где бы вы ни были. Аллах видит все, что вы совершаете.","Ему принадлежит власть над небесами и землей, и к Аллаху возвращаются дела.","Он увеличивает день за счет ночи и увеличивает ночь за счет дня. Он знает о том, что в груди.","Веруйте в Аллаха и Его Посланника и расходуйте из того, что Он дал вам в распоряжение. Тем же из вас, которые уверовали и расходовали, уготована великая награда.","Что с вами? Почему вы не веруете в Аллаха, тогда как Посланник призывает вас уверовать в вашего Господа? Он уже взял с вас завет, если только вы действительно являетесь верующими.","Он - Тот, Кто ниспосылает Своему рабу ясные знамения, чтобы вывести вас из мраков к свету. Воистину, Аллах сострадателен и милосерден к вам.","Что с вами? Почему вы не расходуете на пути Аллаха, тогда как Аллаху принадлежит наследство небес и земли. Не сравнятся люди с теми из вас, кто расходовал и сражался до победы над Меккой. Эти выше степенью, чем те, которые расходовали и сражались после этого. Но каждому из них Аллах обещал наилучшее, и Аллах ведает о том, что вы совершаете.","Если кто одолжит Аллаху прекрасный заем, то Аллах увеличит его для него. Ему уготована щедрая награда.","в тот день, когда ты увидишь, как перед верующими мужчинами и верующими женщинами и справа от них будет распространяться их свет. Возрадуйтесь сегодня Райским садам, в которых текут реки. Вы пребудете в них вечно. Это и есть великое преуспеяние.","В тот день лицемеры и лицемерки скажут верующим: «Погодите, мы позаимствуем у вас немного света». Им будет сказано: «Возвращайтесь назад и ищите свет». Между ними будет возведен забор с вратами, с внутренней стороны которого будет милость, а снаружи - мучения.","Они будут взывать к ним: «Разве мы не были с вами?». Они скажут: «Да, но вы соблазняли самих себя, выжидали, сомневались и обольщались надеждами до тех пор, пока не явилось повеление Аллаха. Соблазнитель (дьявол) обманул вас относительно Аллаха.","Сегодня ни от вас, ни от неверующих не примут выкупа. Вашим пристанищем будет Огонь, который более всего подобает вам. Как же скверно это место прибытия!».","Разве не пришло время для того, чтобы сердца верующих смирились при упоминании Аллаха и того, что ниспослано из истины, и чтобы не уподоблялись они тем, которым Писание было даровано прежде, чьи сердца почерствели по прошествии долгого времени и многие из которых являются нечестивцами?","Знайте, что Аллах оживляет землю после ее смерти. Мы уже разъяснили вам знамения, - может быть, вы уразумеете.","Воистину, для мужчин и женщин, которые раздавали милостыню и одолжили Аллаху прекрасный заем, он будет увеличен. Им уготована щедрая награда.","Уверовавшие в Аллаха и Его посланников - это правдивейшие люди. А павшие мученики находятся возле своего Господа, и им уготованы их награда и их свет. А те, которые не уверовали и сочли ложью Наши знамения, являются обитателями Ада.","Знайте, что мирская жизнь - всего лишь игра и потеха, украшение и похвальба между вами, а также стремление обрести побольше богатства и детей. Она подобна дождю, растения после которого восхищают земледельцев, но потом они высыхают, и ты видишь их пожелтевшими, после чего они превращаются в труху. А в Последней жизни есть тяжкие мучения и прощение от Аллаха и довольство. Мирская жизнь - всего лишь предмет обольщения.","Стремитесь же к прощению от вашего Господа и Раю, ширина которого подобна ширине неба и земли. Он уготован для тех, которые уверовали в Аллаха и Его посланников. Такова милость Аллаха, которую Он дарует тем, кому пожелает. Аллах обладает великой милостью.","Любое несчастье, которое происходит на земле и с вами самими, записано в Писании еще до того, как Мы сотворили его. Воистину, это для Аллаха легко.","Мы поведали об этом для того, чтобы вы не печалились о том, что вы упустили, и не радовались тому, что Он вам даровал. Аллах не любит всяких надменных бахвалов,","которые скупятся и велят людям скупиться. А если кто отвернется, то ведь Аллах - Богатый, Достохвальный.","Мы уже отправили Наших посланников с ясными знамениями и ниспослали с ними Писание и Весы, чтобы люди придерживались справедливости. Мы также ниспослали железо, в котором заключается могучая сила и польза для людей, для того, чтобы Аллах узнал тех, кто помогает Ему и Его посланникам, хотя и не видит Его воочию. Воистину, Аллах - Всесильный, Могущественный.","Мы уже отправили Нуха (Ноя) и Ибрахима (Авраама) и установили пророчество и Писание в их потомстве. Среди них есть такие, которые следуют прямым путем, но многие из них являются нечестивцами.","Потом Мы отправили по их следам Наших посланников, и отправили Ису (Иисуса), сына Марьям (Марии), и даровали ему Инджил (Евангелие). В сердца тех, которые последовали за ним, Мы вселили сострадание и милосердие, а монашество они выдумали сами. Мы не предписывали им этого, но они поступили так, дабы снискать довольство Аллаха (или Мы предписали им только стремиться к довольству Аллаха). Но они не соблюли его должным образом. Тем из них, которые уверовали, Мы даровали их награду, но многие из них являются нечестивцами.","О те, которые уверовали! Бойтесь Аллаха и веруйте в Его Посланника, и тогда Он одарит вас вдвойне из Своей милости, и дарует вам свет, при котором вы будете идти, и простит вас. Аллах - Прощающий, Милосердный.","Аллах одарит вас для того, чтобы люди Писания знали, что они ничего не способны приобрести из милости Аллаха и что милость находится в Руке Аллаха, Который дарует ее тому, кому пожелает. Аллах обладает великой милостью."],"58":["Аллах уже услышал слова женщины, которая вступила с тобой в пререкания относительно своего мужа и пожаловалась Аллаху. Аллах слышал ваш спор, ведь Аллах - Слышащий, Видящий.","Те из вас, которые объявляют своих жен запретными для себя, говорят слова предосудительные и лживые. Их жены - не матери им, ведь их матерями являются только женщины, которые их родили. Воистину, Аллах - Снисходительный, Прощающий.","Те, которые объявляют своих жен запретными для себя, а потом отрекаются от сказанного, должны освободить одного раба прежде, чем они прикоснутся друг к другу. Этим вас увещевают, и Аллах ведает о том, что вы совершаете.","Если кто-либо не сможет сделать этого, то он должен поститься в течение двух месяцев без перерыва прежде, чем они прикоснутся друг к другу. А кто не способен на это, тому надлежит накормить шестьдесят бедняков. Это делается для того, чтобы вы уверовали в Аллаха и Его Посланника. Таковы ограничения Аллаха, а для неверующих уготованы мучительные страдания.","Те, которые враждуют с Аллахом и Его Посланником, будут унижены, как были унижены их предшественники. Мы уже ниспослали ясные знамения, а для неверующих уготованы унизительные мучения.","В тот день Аллах воскресит их всех и поведает им о том, что они совершили. Аллах исчислил это, а они забыли. Аллах - Свидетель всякой вещи.","Разве ты не знаешь, что Аллаху ведомо то, что на небесах, и то, что на земле? Не бывает тайной беседы между тремя, чтобы Он не был четвертым; или между пятью, чтобы Он не был шестым. Больше их или меньше - Он всегда с ними, где бы они ни были. А потом, в День воскресения, Он поведает им о том, что они совершили. Воистину, Аллах знает о всякой вещи.","Разве ты не видел тех, кому были запрещены тайные беседы. Они возвращаются к тому, что было им запрещено, и тайно переговариваются о грехах, посягательстве и неповиновении Посланнику. Когда они приходят к тебе, то приветствуют тебя не так, как приветствует тебя Аллах, говоря в душе: «Почему бы Аллаху не наказать нас за то, что мы говорим?». Довольно с них Геенны! Туда они попадут, и как же скверно это место прибытия!","О те, которые уверовали! Если уж вы тайно переговариваетесь, то не говорите о грехах, посягательстве и неповиновении Посланнику, а говорите о благочестии и богобоязненности и бойтесь Аллаха, к Которому вы будете собраны.","Тайная беседа - от дьявола, стремящегося опечалить тех, которые уверовали. Но это нисколько не повредит им, если на то не будет соизволения Аллаха. Пусть же верующие уповают только на Аллаха.","О те, которые уверовали! Когда вас просят на собраниях сесть пошире, то садитесь пошире, и Аллах одарит вас местом просторным. Когда же вам велят подняться, то поднимайтесь. Аллах возвышает по степеням тех из вас, кто уверовал, и тех, кому даровано знание. Аллах ведает о том, что вы совершаете.","О те, которые уверовали! Если вы беседуете с Посланником в тайне, то предварите вашу тайную беседу милостыней. Так будет лучше для вас и чище. Но если вы ничего не найдете, то ведь Аллах - Прощающий, Милосердный.","Неужели вы боялись предварять вашу тайную беседу милостыней? Если вы не сделали этого и Аллах принял ваше покаяние, то совершайте намаз, выплачивайте закят и повинуйтесь Аллаху и Его Посланнику. Аллах ведает о том, что вы совершаете.","Разве ты не видел тех, которые дружат с людьми, на которых разгневался Аллах? Они не относятся ни к вам, ни к ним. Они дают заведомо ложные клятвы.","Аллах приготовил для них тяжкие мучения. Воистину, скверно то, что они совершают!","Они сделали свои клятвы щитом и сбили других с пути Аллаха. Им уготованы унизительные мучения.","Ни имущество, ни дети ничем не помогут им пред Аллахом. Они являются обитателями Огня и пребудут там вечно.","В тот день, когда Аллах воскресит их всех, они станут клясться перед Ним, подобно тому, как клянутся перед вами, полагая, что это поможет им. Воистину, они - лжецы.","Дьявол одолел их и заставил их забыть о поминании Аллаха. Они являются партией дьявола. Воистину, партия дьявола - это потерпевшие убыток.","Те, которые враждуют с Аллахом и Его Посланником, окажутся в числе самых униженных.","Аллах предписал: «Победу непременно одержим Я и Мои посланники!». Воистину, Аллах - Всесильный, Могущественный.","Среди тех, кто верует в Аллаха и в Последний день, ты не найдешь людей, которые любили бы тех, кто враждует с Аллахом и Его Посланником, даже если это будут их отцы, сыновья, братья или родственники. Аллах начертал в их сердцах веру и укрепил их духом от Него. Он введет их в Райские сады, в которых текут реки, и они пребудут там вечно. Аллах доволен ими, и они довольны Им. Они являются партией Аллаха. Воистину, партия Аллаха - это преуспевшие."],"59":["Славит Аллаха то, что на небесах, и то, что на земле. Он - Могущественный, Мудрый.","Он - Тот, Кто изгнал неверующих людей Писания из их жилищ при первом сборе. Вы не полагали, что они уйдут. Они же думали, что их крепости защитят их от Аллаха. Но Аллах настиг их оттуда, откуда они не предполагали, и бросил в их сердца страх. Они разрушают свои дома собственными руками и руками верующих. Прислушайтесь же к назиданию, о обладающие зрением!","Если бы Аллах не предписал им исход, то Он непременно наказал бы их в этом мире. А в Последней жизни им уготованы мучения в Огне.","Это - за то, что они воспротивились Аллаху и Его Посланнику. Если же кто-либо противится Аллаху, то ведь Аллах суров в наказании.","Срубили ли вы финиковые пальмы или оставили их стоять на их стволах - на то было соизволение Аллаха, дабы опозорить нечестивцев.","К добыче, которую Аллах вернул Своему Посланнику, вы не скакали рысью ни на конях, ни на верблюдах, но Аллах дарует Своим посланникам власть, над кем пожелает. Аллах способен на всякую вещь.","Добыча, которую Аллах вернул Своему Посланнику от жителей селений, принадлежит Аллаху, Посланнику, родственникам Пророка, сиротам, бедным и путникам, дабы не досталась она богатым среди вас. Берите же то, что дал вам Посланник, и сторонитесь того, что он запретил вам. Бойтесь Аллаха, ведь Аллах суров в наказании.","А также неимущим мухаджирам, которые были изгнаны из своих жилищ и лишены своего имущества. Они стремятся к милости Аллаха и довольству и помогают Аллаху и Его Посланнику. Они являются правдивыми.","А те, которые жили в доме (Медине) и обрели веру до них, любят переселившихся к ним и не ощущают никакой нужды к тому, что даровано им. Они отдают им предпочтение перед собой, даже если они сами нуждаются. А те, кто уберегся от собственной скупости, являются преуспевшими.","А те, которые пришли после них, говорят: «Господь наш! Прости нас и наших братьев, которые уверовали раньше нас! Не насаждай в наших сердцах ненависти и зависти к тем, кто уверовал. Господь наш! Воистину, Ты - Сострадательный, Милосердный».","Разве ты не видишь, что лицемеры говорят своим неверующим братьям из числа людей Писания: «Если вас изгонят, то мы уйдем вместе с вами и никогда никому не подчинимся против вас. А если с вами сразятся, то мы обязательно поможем вам». Аллах свидетельствует о том, что они являются лжецами.","Если они будут изгнаны, то те не уйдут вместе с ними. Если с ними сразятся, то они не помогут им. А если даже они помогут им, то повернут вспять, после чего уже никто не поможет им.","Воистину, они страшатся вас в сердцах сильнее, чем Аллаха, поскольку они являются людьми непонимающими.","Они не станут сражаться с вами вместе, разве что в укрепленных селениях или из-за стен. Меж собой у них жестокая вражда. Ты полагаешь, что они едины, но сердца их разобщены. Это потому, что они - люди неразумные.","Они подобны своим недавним предшественникам, которые вкусили пагубность своих деяний и которым уготованы мучительные страдания.","Они подобны дьяволу, который говорит человеку: «Не веруй!». Когда же тот становится неверующим, он говорит: «Я не причастен к тебе! Я боюсь Аллаха, Господа миров».","Концом тех и других станет попадание в Огонь, в котором они пребудут вечно. Таково воздаяние беззаконникам!","О те, которые уверовали! Бойтесь Аллаха, и пусть душа посмотрит, что она приготовила на завтрашний день. Бойтесь Аллаха, ведь Аллах ведает о том, что вы совершаете.","Не будьте подобны тем, которые забыли Аллаха, и Он заставил забыть самих себя. Они являются нечестивцами.","Обитатели Огня не равны обитателям Рая. Обитатели Рая являются преуспевшими.","Если бы Мы ниспослали этот Коран горе, то ты увидел бы, как она смиренно раскалывается от страха перед Аллахом. Такие притчи Мы приводим людям для того, чтобы они поразмыслили.","Он - Аллах, и нет божества, кроме Него, Ведающего сокровенное и явное. Он - Милостивый, Милосердный.","Он - Аллах, и нет божества, кроме Него, Властелина, Святого, Пречистого, Оберегающего, Хранителя, Могущественного, Могучего, Гордого. Пречист Аллах и далек от того, что они приобщают в сотоварищи.","Он - Аллах, Творец, Создатель, Дарующий облик. У Него - самые прекрасные имена. Славит Его то, что на небесах и на земле. Он - Могущественный, Мудрый."],"60":["О те, которые уверовали! Не берите врага Моего и врага вашего своим покровителем и помощником. Вы открываетесь им с любовью, хотя они не веруют в истину, которая явилась вам. Они изгоняют Посланника и вас за то, что вы веруете в Аллаха, вашего Господа. Если вы выступили, чтобы сражаться на Моем пути и снискать Мое довольство, то не питайте к ним любви в тайне. Я знаю то, что вы скрываете, и то, что вы обнародуете. А кто из вас поступает таким образом, тот сбился с прямого пути.","Если они случайно встретятся с вами, то они окажутся вашими врагами, будут вредить вам своими руками и языками и захотят, чтобы вы стали неверующими.","Ни ваши родственники, ни ваши дети не помогут вам. В День воскресения Он рассудит между вами. Аллах видит то, что вы совершаете.","Прекрасным примером для вас были Ибрахим (Авраам) и те, кто был с ним. Они сказали своему народу: «Мы отрекаемся от вас и тех, кому вы поклоняетесь вместо Аллаха. Мы отвергаем вас, и между нами и вами установились вражда и ненависть навеки, пока вы не уверуете в одного Аллаха». Лишь только Ибрахим (Авраам) сказал своему отцу: «Я обязательно буду просить для тебя прощения, но я не властен помочь тебе перед Аллахом. Господь наш! На Тебя одного мы уповаем, к Тебе одному мы обращаемся, и к Тебе предстоит прибытие.","Господь наш! Не делай нас искушением для тех, которые не веруют. Господь наш, прости нас, ведь Ты - Могущественный, Мудрый».","Они были прекрасным примером для вас - для тех, кто надеется на Аллаха и на Последний день. А если кто-либо отвернется, то ведь Аллах - Богатый, Достохвальный.","Может быть, Аллах установит дружбу между вами и теми, с кем вы враждуете. Аллах - Всемогущий. Аллах - Прощающий, Милосердный.","Аллах не запрещает вам быть добрыми и справедливыми с теми, которые не сражались с вами из-за религии и не изгоняли вас из ваших жилищ. Воистину, Аллах любит беспристрастных.","Аллах запрещает вам дружить только с теми, которые сражались с вами из-за религии, выгоняли вас из ваших жилищ и способствовали вашему изгнанию. А те, которые берут их себе в помощники и друзья, являются беззаконниками.","О те, которые уверовали! Когда к вам прибывают переселившиеся верующие женщины, то подвергайте их испытанию. Аллаху лучше знать об их вере. Если вы узнаете, что они являются верующими, то не возвращайте их неверующим, ибо им не дозволено жениться на них, а им не дозволено выходить замуж за них. Возвращайте им (неверующим) то, что они потратили на брачный дар. На вас не будет греха, если вы женитесь на них после уплаты их вознаграждения (брачного дара). Не держитесь за узы с неверующими женами и требуйте назад то, что вы потратили на брачный дар. И пусть они (неверующие) требуют то, что они потратили на брачный дар. Таково решение Аллаха. Он решает между вами. Аллах - Знающий, Мудрый.","Если какая-либо из ваших жен ушла от вас к неверующим, после чего вы получили военную добычу, то отдайте тем, жены которых ушли, потраченное ими на брачный дар. Бойтесь Аллаха, в Которого вы веруете.","О Пророк! Если к тебе придут верующие женщины, чтобы присягнуть в том, что они не будут приобщать сотоварищей к Аллаху, красть, прелюбодействовать, убивать своих детей, покрывать клеветой то, что между их руками и ногами, и ослушаться тебя в благих делах, то прими у них присягу и попроси у Аллаха прощения для них. Воистину, Аллах - Прощающий, Милосердный.","О те, которые уверовали! Не дружите с теми, на кого разгневался Аллах. Они потеряли надежду на Последнюю жизнь, как потеряли ее неверующие обитатели могил (или как неверующие потеряли надежду на воскрешение обитателей могил)."],"61":["Славит Аллаха то, что на небесах, и то, что на земле. Он - Могущественный, Мудрый.","О те, которые уверовали! Почему вы говорите то, чего не делаете?","Велика ненависть Аллаха к тому, что вы говорите то, чего не делаете.","Воистину, Аллах любит тех, которые сражаются на Его пути рядами, словно они - прочное строение.","Вот сказал Муса (Моисей) своему народу: «О мой народ! Почему вы причиняете мне страдания, зная, что я послан к вам Аллахом?». Когда же они уклонились, Аллах совратил их сердца. Аллах не ведет прямым путем людей нечестивых.","А вот Иса (Иисус), сын Марьям (Марии), сказал: «О сыны Исраила (Израиля)! Я послан к вам Аллахом, чтобы подтвердить правдивость того, что было в Таурате (Торе) до меня, и чтобы сообщить благую весть о Посланнике, который придет после меня, имя которого будет Ахмад (Мухаммад)». Когда же он явился к ним с ясными знамениями, они сказали: «Это - очевидное колдовство».","Кто же может быть несправедливее того, кто измышляет ложь об Аллахе, когда его призывают к исламу? Аллах не ведет прямым путем несправедливых людей.","Они хотят погасить свет Аллаха своими ртами, но Аллах сохранит Свой свет, даже если это ненавистно неверующим.","Он - Тот, Кто отправил Своего Посланника с верным руководством и религией истины, чтобы превознести ее над всеми остальными религиями, даже если это ненавистно многобожникам.","О те, которые уверовали! Указать ли вам на торговлю, которая спасет вас от мучительных страданий?","Веруйте в Аллаха и Его Посланника и сражайтесь на пути Аллаха своим имуществом и своими душами. Так будет лучше для вас, если бы вы только знали.","Он простит вам ваши грехи, введет вас в Райские сады, в которых текут реки, и в прекрасные жилища в садах Эдема. Это - великое преуспеяние.","Будет еще то, что вы любите: помощь от Аллаха и близкая победа. Сообщи же благую весть верующим!","О те, которые уверовали! Будьте помощниками Аллаха. Иса (Иисус), сын Марьям (Марии), сказал апостолам: «Кто будет моим помощником на пути к Аллаху?». Апостолы ответили: «Мы - помощники Аллаха». Часть сынов Исраила (Израиля) уверовала, а другая часть не уверовала. Мы поддержали тех, которые уверовали, в борьбе с их врагами, и они вышли победителями."],"62":["То, что на небесах, и то, что на земле, славит Аллаха - Властелина, Святого, Могущественного, Мудрого.","Он - Тот, Кто отправил к неграмотным людям Посланника из их среды. Он читает им Его аяты, очищает их и обучает их Писанию и мудрости, хотя прежде они пребывали в очевидном заблуждении.","А также к тем, которые не застали их. Он - Могущественный, Мудрый.","Такова милость Аллаха. Он дарует ее, кому пожелает. Аллах обладает великой милостью.","Те, кому было поручено придерживаться Таурата (Торы) и которые не придерживались его, подобны ослу, который везет на себе много книг. Как же скверно сравнение с людьми, которые считают ложью знамения Аллаха! Аллах не ведет прямым путем несправедливых людей.","Скажи: «О исповедующие иудаизм! Если вы полагаете, что только вы среди людей являетесь угодниками Аллаха, то пожелайте себе смерти, если вы говорите правду».","Но они никогда не пожелают этого из-за того, что приготовили их руки. Аллаху известно о беззаконниках.","Скажи: «Смерть, от которой вы убегаете, настигнет вас, после чего вы вернетесь к Ведающему сокровенное и явное, и Он сообщит вам о том, что вы совершали».","О те, которые уверовали! Когда призывают на намаз в пятничный день, то устремляйтесь к поминанию Аллаха и оставьте торговлю. Так будет лучше для вас, если бы вы только знали.","Когда же намаз завершится, то разойдитесь по земле, ищите милость Аллаха и часто поминайте Его, - быть может, вы преуспеете.","Когда же они увидели торговлю или забаву, они разошлись, бросившись к ней, и оставили тебя стоять во время пятничной проповеди. Скажи: «То, что у Аллаха, лучше забавы и торговли, и Аллах - Наилучший из дарующих удел»."],"63":["Когда лицемеры приходят к тебе, они говорят: «Свидетельствуем, что ты - Посланник Аллаха». Аллах знает, что ты - Его Посланник, и Аллах свидетельствует, что лицемеры являются лжецами.","Они сделали свои клятвы щитом и сбили других с пути Аллаха. Воистину, скверно то, что они совершают!","Это потому, что они уверовали, а затем стали неверующими. Затем их сердца были запечатаны, и теперь они не разумеют.","Когда ты смотришь на них, их тела восхищают тебя. Когда они говорят, ты слушаешь их слова. Они подобны прислоненным бревнам. Всякий крик они считают обращенным против них. Они являются врагами - остерегайся же их. Да погубит их Аллах! До чего же они отвращены от истины!","Когда им говорят: «Придите, чтобы Посланник Аллаха попросил для вас прощения», - они качают головой, и ты видишь, как они надменно отворачиваются.","Попросишь ты для них прощения или не станешь просить для них прощения - им все равно. Аллах не простит их. Воистину, Аллах не ведет прямым путем нечестивых людей.","Именно они говорят: «Ничего не тратьте на тех, кто возле Посланника Аллаха, пока они не покинут его». Аллаху принадлежат сокровищницы небес и земли, но лицемеры не понимают этого.","Они говорят: «Когда мы вернемся в Медину, то могущественные среди нас непременно изгонят оттуда презренных». Могущество присуще Аллаху, Его Посланнику и верующим, но лицемеры не знают этого.","О те, которые уверовали! Пусть ваше имущество и ваши дети не отвлекают вас от поминания Аллаха. А те, которые поступают таким образом, окажутся потерпевшими убыток.","Расходуйте из того, чем Мы вас наделили, до того, как вас постигнет смерть и вы скажете: «Господи! Предоставь мне недолгую отсрочку, и я буду раздавать милостыню и стану одним из праведников».","Аллах не предоставит отсрочки душе, если наступил ее срок. Аллах ведает о том, что вы совершаете."],"64":["Славит Аллаха то, что на небесах, и то, что на земле. Ему принадлежит власть и надлежит хвала. Он способен на всякую вещь.","Он - Тот, Кто сотворил вас. Среди вас есть неверующие, и среди вас есть верующие. Аллах видит то, что вы совершаете.","Он создал небеса и землю ради истины, придал вам облик и сделал ваш облик прекрасным. К Нему предстоит прибытие.","Он знает о том, что на небесах и на земле, и знает о том, что вы скрываете и что обнародуете. Аллах ведает о том, что в груди.","Разве до вас не дошли рассказы о тех, которые не уверовали в прошлом и вкусили пагубные последствия своих деяний? Им уготованы мучительные страдания.","Это - за то, что посланники приходили к ним с ясными знамениями, а они говорили: «Неужели люди поведут нас прямым путем?». Они не уверовали и отвернулись. Аллах обошелся без них, ведь Аллах - Богатый, Достохвальный.","Неверующие полагают, что они не будут воскрешены. Скажи: «Напротив, клянусь моим Господом, вы непременно будете воскрешены, а затем вам непременно сообщат о том, что вы совершили. Это для Аллаха легко».","Уверуйте же в Аллаха, Его Посланника и свет, который Мы ниспослали. Аллах ведает о том, что вы совершаете.","В тот день Он соберет вас для Дня сбора. Это будет День взаимного обделения. Тем, кто уверовал в Аллаха и поступал праведно, Он простит злодеяния и введет их в Райские сады, в которых текут реки. Они пребудут там вечно. Это - великое преуспеяние!","А те, которые не уверовали и сочли ложью Наши знамения, станут обитателями Огня. Они пребудут там вечно. Как же скверно это место прибытия!","Любое несчастье постигает только по воле Аллаха. Сердце того, кто уверовал в Аллаха, Он наставляет на прямой путь. Аллах знает о всякой вещи.","Повинуйтесь Аллаху и повинуйтесь Посланнику. Если же вы отвернетесь, то ведь на Нашего Посланника возложена только ясная передача откровения.","Аллах - нет божества, кроме Него. Пусть же верующие уповают только на Аллаха.","О те, которые уверовали! Воистину, среди ваших жен и ваших детей есть враги вам. Остерегайтесь их, но если вы будете снисходительны, проявите великодушие и простите их, то ведь Аллах - Прощающий, Милосердный.","Воистину, ваше имущество и ваши дети являются искушением. У Аллаха же есть великая награда.","Бойтесь Аллаха по мере своих возможностей, слушайте, повинуйтесь и расходуйте во благо самим себе. А те, кто уберегся от собственной скупости, являются преуспевшими.","Если вы одолжите Аллаху прекрасный заем, то Он приумножит его для вас и простит вас. Аллах - Благодарный, Выдержанный,","Ведающий сокровенное и явное, Могущественный, Мудрый."],"65":["О Пророк! Когда вы даете женам развод, то разводитесь в течение установленного срока, ведите счет этому сроку и бойтесь Аллаха, вашего Господа. Не выгоняйте их из их домов, и пусть они не выходят из них, если только они не совершат явную мерзость. Таковы ограничения Аллаха. Кто преступает ограничения Аллаха, тот поступает несправедливо по отношению к себе. Ты не знаешь, что Аллах, возможно, после этого решит иначе.","Когда для них наступит установленный срок, оставьте их у себя по-хорошему или же отпустите по-хорошему. Призовите свидетелями двух справедливых мужей из вас и будьте свидетелями ради Аллаха. Таково увещевание для тех, кто верует в Аллаха и в Последний день. Тому, кто боится Аллаха, Он создает выход из положения","и наделяет его уделом оттуда, откуда он даже не предполагает. Тому, кто уповает на Аллаха, достаточно Его. Аллах доводит до конца Свое дело. Аллах установил меру для каждой вещи.","Для тех из ваших женщин, у которых прекратились менструации, если вы сомневаетесь, установленный для развода срок равен трем месяцам, как и для тех, у которых не было менструаций. Для беременных срок установлен до тех пор, пока они не разрешатся от бремени. Тому, кто боится Аллаха, Он облегчает дела.","Таково повеление Аллаха, которое Он ниспослал вам. Тому, кто боится Аллаха, Он простит злодеяния и увеличит награду.","Поселяйте их там, где вы живете сами - по вашему достатку. Не причиняйте им вреда, желая стеснить их. Если они беременны, то содержите их, пока они не разрешатся от бремени. Если они кормят грудью для вас, то платите им вознаграждение и советуйтесь между собой по-хорошему. Если же вы станете обременять друг друга, то кормить для него будет другая женщина.","Пусть обладающий достатком расходует согласно своему достатку. А тот, кто стеснен в средствах, пусть расходует из того, чем его одарил Аллах. Аллах не возлагает на человека сверх того, что Он даровал ему. После тяготы Аллах создает облегчение.","Сколько городов ослушались повелений своего Господа и Его посланников! Мы представили им суровый счет и подвергли их ужасным мучениям.","Они вкусили пагубные последствия своих деяний, и исходом их деяний стал убыток.","Аллах приготовил для них тяжкие мучения. Бойтесь же Аллаха, о обладающие разумом, которые уверовали. Аллах уже ниспослал вам напоминание -","Посланника, который читает вам ясные аяты Аллаха, чтобы вывести тех, которые уверовали и совершали праведные деяния, из мраков к свету. Тех, которые уверовали в Аллаха и поступали праведно, Аллах введет в Райские сады, в которых текут реки. Они пребудут там вечно. Аллах уже сделал их удел прекрасным!","Аллах - Тот, Кто сотворил семь небес и столько же земель. Повеление нисходит между ними, чтобы вы знали, что Аллах способен на всякую вещь и что Аллах объемлет знанием всякую вещь."],"66":["О Пророк! Почему ты запрещаешь себе то, что позволил тебе Аллах, стремясь угодить своим женам? Аллах - Прощающий, Милосердный.","Аллах установил для вас путь освобождения от ваших клятв. Аллах - ваш Покровитель. Он - Знающий, Мудрый.","Вот Пророк открыл тайну одной из своих жен. Когда же она рассказала ее, и Аллах открыл это ему, он дал знать о части этого и утаил другую часть. Она сказала: «Кто сообщил тебе об этом?». Он сказал: «Мне сообщил Знающий, Ведающий».","Если вы обе покаетесь перед Аллахом, то ведь ваши сердца уже уклонились в сторону. Если же вы станете поддерживать друг друга против него, то ведь ему покровительствует Аллах, а Джибрил (Гавриил) и праведные верующие являются его друзьями. А, кроме того, ангелы помогают ему.","Если он разведется с вами, то его Господь может заменить вас женами, которые будут лучше вас, и будут мусульманками, верующими, покорными, кающимися, поклоняющимися, постящимися, как побывавшими замужем, так и девственницами.","О те, которые уверовали! Оберегайте себя и свои семьи от Огня, растопкой которого будут люди и камни. Над ним есть ангелы суровые и сильные. Они не отступают от повелений Аллаха и выполняют все, что им велено.","О те, которые не уверовали! Не оправдывайтесь сегодня. Вам воздают только за то, что вы совершали.","О те, которые уверовали! Раскаивайтесь перед Аллахом искренне! Может быть, ваш Господь простит ваши злодеяния и введет вас в Райские сады, в которых текут реки, в тот день, когда Аллах не опозорит Пророка и тех, кто уверовал вместе с ним. Их свет будет сиять перед ними и справа. Они скажут: «Господь наш! Дай нам света сполна и прости нас. Воистину, Ты способен на всякую вещь».","О Пророк! Сражайся с неверующими и лицемерами и будь суров с ними. Их пристанищем будет Геенна. Как же скверно это место прибытия!","Аллах привел в качестве примера о неверующих жену Нуха (Ноя) и жену Лута (Лота). Обе были замужем за рабами из числа Наших праведных рабов. Они предали своих мужей, и те не спасли их от Аллаха. Им было сказано: «Войдите в Огонь вместе с теми, кто входит туда».","А в качестве примера о верующих Аллах привел жену Фараона. Вот она сказала: «Господи! Спаси меня от Фараона и его деяний! Возведи для меня дом в Раю возле Тебя и спаси меня от несправедливых людей!».","А также Марьям (Марию), дочь Имрана, которая сберегла целомудрие, и Мы вдохнули в него (в вырез на ее одежде) от Нашего духа. Она уверовала в Слова своего Господа и Его Писания и была одной из покорных."],"67":["Благословен Тот, в Чьей Руке власть, Кто способен на всякую вещь,","Кто сотворил смерть и жизнь, чтобы испытать вас и увидеть, чьи деяния окажутся лучше. Он - Могущественный, Прощающий.","Он создал семь небес одно над другим. В творении Милостивого ты не увидишь никакой несообразности. Взгляни еще раз. Видишь ли ты какую-нибудь трещину?","Потом взгляни еще раз и еще раз, и твой взор вернется к тебе униженным, утомленным.","Воистину, Мы украсили ближайшее небо светильниками и установили их для метания в дьяволов. Мы приготовили для них мучения в Пламени.","Для тех, кто не уверовал в своего Господа, приготовлены мучения в Геенне. Как же скверно это место прибытия!","Когда их бросят туда, они услышат, как она ревет, когда кипит.","Она готова разорваться от ярости. Каждый раз, когда туда будут бросать толпу, ее стражи будут спрашивать их: «Разве к вам не приходил предостерегающий увещеватель?».","Они скажут: «Конечно, предостерегающий увещеватель приходил к нам, но мы сочли его лжецом и сказали: «Аллах ничего не ниспосылал, а вы лишь пребываете в большом заблуждении»».","Они скажут: «Если бы мы прислушивались и были рассудительны, то не оказались бы среди обитателей Пламени».","Они признаются в своем грехе. Прочь же, обитатели Пламени!","Воистину, тем, которые боятся своего Господа, не видя Его воочию, уготованы прощение и великая награда.","Храните ли вы свои речи в секрете или же говорите о них вслух, Он ведает о том, что в груди.","Неужели этого не будет знать Тот, Кто сотворил, если Он - Проницательный (или Добрый), Ведающий?","Он - Тот, Кто сделал для вас землю покорной. Ступайте же по свету и вкушайте из Его удела, и к Нему вы явитесь после воскрешения.","Неужели вы уверены, что Тот, Кто на небе, не заставит землю поглотить вас? Ведь тогда она заколеблется.","Неужели вы уверены, что Тот, Кто на небе, не нашлет на вас ураган с камнями? Скоро вы узнаете, каково Мое предостережение!","Жившие до них сочли это ложью. Каким же было Мое обличение!","Неужели они не видели над собой птиц, которые простирают и складывают крылья? Никто не удерживает их, кроме Милостивого. Воистину, Он видит всякую вещь.","Кто может стать вашим войском и помочь вам без Милостивого? Воистину, неверующие обольщены!","Кто может наделить вас уделом, если Он перестанет наделять вас Своим уделом? Но они продолжают ослушаться и убегать.","Кто же следует более правильным путем: блуждающий с опущенным лицом или идущий по прямому пути, выпрямившись?","Скажи: «Он - Тот, Кто создал вас и наделил вас слухом, зрением и сердцами. Как же мала ваша благодарность!».","Скажи: «Он - Тот, Кто расселил вас по земле, и к Нему вы будете собраны».","Они говорят: «Когда же наступит обещанное, если вы говорите правду?».","Скажи: «Знание об этом - у Аллаха, а я - всего лишь предостерегающий и разъясняющий увещеватель».","Когда они увидят его (наказание в День воскресения) вблизи от себя, лица неверующих опечалятся, и тогда им скажут: «Вот то, что вы призывали!».","Скажи: «Как вы думаете, кто защитит от мучительных страданий неверующих, если Аллах погубит меня и тех, кто со мной, или помилует нас?».","Скажи: «Он - Милостивый! Мы уверовали в Него и уповаем только на Него, и вы узнаете, кто пребывает в очевидном заблуждении».","Скажи: «Как вы думаете, кто одарит вас родниковой водой, если ваша вода уйдет под землю?»."],"68":["Нун. Клянусь письменной тростью и тем, что они пишут!","Ты по милости своего Господа не являешься одержимым.","Воистину, награда твоя неиссякаема.","Воистину, твой нрав превосходен.","Ты увидишь, и они тоже увидят,","кто из вас - бесноватый.","Твой Господь лучше знает тех, кто сбился с Его пути, и лучше знает тех, кто следует прямым путем.","Посему не повинуйся тем, кто считает истину ложью!","Они хотели бы, чтобы ты был уступчив, и тогда они тоже стали бы уступчивы.","Не повинуйся всякому расточителю клятв, презренному,","хулителю, разносящему сплетни,","скупящемуся на добро, преступнику, грешнику,","жестокому, к тому же самозванцу,","даже если он будет богат и будет иметь сыновей.","Когда ему читают Наши аяты, он говорит: «Это - легенды древних народов!».","Мы заклеймим его хобот (нос).","Воистину, мы подвергли их испытанию, подобно тому, как мы подвергли испытанию владельцев сада, когда они поклялись, что утром они непременно сорвут их (плоды),","но не сделали оговорки (не сказали: «Если того пожелает Аллах»).","Ночью же, пока они спали, их сад поразила кара от твоего Господа.","К утру сад был подобен мрачной ночи (был погублен).","А на рассвете они стали звать друг друга:","«Ступайте на вашу пашню, если вы хотите сорвать плоды!».","Они отправились туда, разговаривая шепотом:","«Не впускайте сегодня к себе бедняка».","Они шли с твердым намерением и полагали, что у них достаточно сил.","Когда же они увидели его, они сказали: «Мы сбились с пути!","О нет! Мы лишились этого».","Лучший из них сказал: «Разве я не говорил вам, что надо было прославить Аллаха?».","Они сказали: «Пречист наш Господь! Мы были несправедливы».","Они стали попрекать друг друга","и сказали: «Горе нам! Мы преступили границы дозволенного.","Быть может, Господь наш даст нам взамен нечто лучшее. Воистину, мы обращаемся к нашему Господу».","Такими были мучения, а мучения в Последней жизни будут еще ужаснее! Если бы только они знали!","Воистину, для богобоязненных у их Господа приготовлены Сады блаженства.","Неужели Мы мусульман уравняем с грешниками?","Что с вами? Как вы судите?","Или у вас есть Писание, из которого вы узнали,","что там у вас будет все, что вы выберете?","Или у вас есть Наши клятвы, которые сохранятся до Дня воскресения, о том, что у вас будет все, что вы присудите?","Спроси их, кто из них поручается за это?","Или у них есть сотоварищи? Пусть же они приведут своих сотоварищей, если они говорят правду!","В тот день, когда обнажится Голень Аллаха, их призовут пасть ниц, но они не смогут сделать этого.","Их взоры потупятся, и унижение покроет их. А ведь их призывали пасть ниц, когда они пребывали в здравии.","Оставь же Меня с теми, кто считает ложью это повествование. Мы завлечем их так, что они даже не осознают этого.","Я даю им отсрочку, ведь хитрость Моя несокрушима.","Или же ты просишь у них вознаграждения, и они обременены обязательствами?","Или же они владеют сокровенным и записывают его?","Потерпи же до решения твоего Господа и не уподобляйся человеку в рыбе (Йунусу), который обратился с мольбой вслух, сдерживая свою печаль.","Если бы его не постигла милость Господа, то он был бы выброшен на открытую местность постыженным.","Но его Господь избрал его и сделал одним из праведников.","Воистину, неверующие готовы заставить тебя поскользнуться своими взглядами, когда они слышат Напоминание, и говорят: «Воистину, он - одержимый!».","Но это - не что иное, как Напоминание для миров."],"69":["Неминуемое (День воскресения)!","Что такое Неминуемое (День воскресения)?","Откуда ты мог знать, что такое Неминуемое (День воскресения)?","Самудяне и адиты отрицали Великое бедствие (День воскресения).","Самудяне были истреблены неистовым воплем.","Адиты же были истреблены ветром морозным (или завывающим), лютым.","Он заставил его бушевать над ними в течение семи ночей и восьми дней без перерыва, и ты мог бы увидеть людей, которые были повержены, словно рухнувшие сгнившие пальмовые стволы.","Видишь ли ты что-либо оставшееся от них?","Фараон, его предшественники и опрокинутые селения (селения народа Лута) совершали грехи.","Они ослушались посланника своего Господа, и Он схватил их Хваткой превосходящей.","Когда вода стала разливаться, Мы повезли вас в плавучем ковчеге,","чтобы он стал для вас напоминанием и чтобы запоминающее ухо запомнило это.","Когда же подуют в Рог всего один раз,","когда земля и горы будут подняты и разобьются, превратившись в песок за один раз,","в тот день наступит Событие (День воскресения).","Небо разверзнется, ибо оно в тот день будет слабым.","Ангелы будут находиться по его краю, и восьмеро понесут над собой Трон твоего Господа.","В тот день вы предстанете, и ни одна ваша тайна не останется сокрытой.","Тот, кому его книга будет дана в правую руку, скажет: «Вот! Прочтите мою книгу!","Я верил в то, что мне предъявят счет».","Для него будет отрадная жизнь","в вышнем саду,","где плоды склоняются низко.","Ешьте и пейте во здравие за то, что вы совершили в минувшие дни!","Тот же, кому его книга будет дана в левую руку, скажет: «Лучше бы мне не вручали моей книги!","Не знать бы мне, каков мой счет!","Лучше бы она была концом всего!","Не помогло мне мое богатство!","Лишился я своей власти!».","Схватите его и закуйте,","потом бросьте его в Ад","и нанизьте его на цепь длиной в семьдесят локтей!","Он не веровал в Великого Аллаха","и не призывал кормить бедняка.","Сегодня здесь у него нет любящего родственника,","и нет пищи, кроме кровавого гноя.","Едят его только грешники.","О да! Клянусь тем, что вы видите,","и тем, чего вы не видите!","Это - слова благородного посланца (Мухаммада или Джибрила).","Это - не слова поэта. Мало же вы веруете!","Это - не слова прорицателя. Мало же вы поминаете назидания!","Это - Ниспослание от Господа миров.","Если бы он приписал Нам некоторые слова,","то Мы схватили бы его за правую руку (или схватили бы его крепко),","а потом перерезали бы ему аорту,","и никто из вас не избавил бы его.","Воистину, это - Назидание для богобоязненных.","Нам известно, что среди вас есть считающие его ложью.","Воистину, это - горе для неверующих.","Воистину, это - убедительная истина.","Прославляй же имя Господа твоего Великого!"],"70":["Просящий просил мучения, которые постигают","неверующих. Никто не сможет предотвратить его","вопреки Аллаху, Владыке ступеней.","Ангелы и Дух (Джибрил) восходят к Нему в течение дня, равного пятидесяти тысячам лет.","Прояви же красивое терпение.","Они считают его далеким.","Мы же видим, что оно близко.","В тот день, когда небо станет подобно расплавленному металлу (или осадку масла; или кровавому гною),","а горы станут подобны шерсти,","родственник не станет расспрашивать родственника,","хотя они будут видеть друг друга. Грешник пожелает откупиться от мучений того дня своими сыновьями,","своей супругой и своим братом,","своим родом, который укрывал его,","и всеми обитателями земли, чтобы затем спастись.","Но нет! Это - Адское пламя,","сдирающее кожу с головы,","зовущее тех, кто повернулся спиной и отвернулся,","кто копил и прятал.","Воистину, человек создан нетерпеливым,","беспокойным, когда его касается беда,","и скупым, когда его касается добро.","Это не относится к молящимся,","которые регулярно совершают свой намаз,","которые выделяют известную долю своего имущества","для просящих и обездоленных,","которые веруют в День воздаяния,","которые трепещут перед мучениями от своего Господа,","ведь мучения от их Господа небезопасны,","которые оберегают свои половые органы от всех,","кроме своих жен и невольниц, которыми овладели их десницы, за что они не заслуживают порицания,","тогда как желающие сверх этого являются преступниками;","которые сохраняют доверенное им и соблюдают договоры,","которые стойки в своих свидетельствах","и которые оберегают свой намаз.","Им будет оказано почтение в Райских садах.","Что же с теми, которые не уверовали и бегут перед тобой","толпами справа и слева?","Неужели каждый из них надеется, что его введут в Сад блаженства?","Но нет! Мы сотворили их из того, что им известно.","Клянусь Господом востоков и западов! Мы способны","заменить их теми, кто лучше них, и никто не превзойдет Нас.","Оставь же их погружаться в словоблудие и забавляться, пока они не встретят тот день их, который им обещан.","В тот день они торопливо выйдут из могил, словно устремляясь к воздвигнутой цели (или идолам; или охотничьей сети).","Их взоры потупятся, и унижение покроет их. Это будет тот день, который им обещан!"],"71":["Мы отправили Нуха (Ноя) к его народу: «Предостереги свой народ прежде, чем их постигнут мучительные страдания».","Он сказал: «О мой народ! Воистину, я для вас - предостерегающий и разъясняющий увещеватель.","Поклоняйтесь Аллаху, бойтесь Его и повинуйтесь мне!","Он простит вам ваши грехи и предоставит вам отсрочку до назначенного срока. Воистину, когда срок Аллаха наступает, он уже не откладывается. Если бы вы только знали!».","Он сказал: «Господи! Я призывал мой народ ночью и днем,","но мои проповеди лишь ускорили их бегство.","Каждый раз, когда я призывал их, чтобы Ты простил их, они затыкали пальцами уши и укрывались одеждами. Они упорствовали и надменно превозносились.","Затем я призывал их открыто.","Затем я обращался к ним всенародно и говорил с ними наедине.","Я говорил: «Просите у вашего Господа прощения, ведь Он - Всепрощающий.","Он ниспошлет вам с неба обильные дожди,","поддержит вас имуществом и детьми, взрастит для вас сады и создаст для вас реки.","Почему вы не чтите величия Аллаха?","Он ведь создавал вас по этапам.","Неужели вы не видели, как Аллах создал семь небес одно над другим,","сделал луну светлой, а солнце сделал светильником?","Аллах вырастил вас из земли, словно растения.","Потом Он вернет вас туда и вновь выведет оттуда.","Аллах сделал для вас землю ковром,","чтобы вы ходили по ней широкими дорогами»».","Нух (Ной) сказал: «Господи! Они ослушались меня и последовали за тем, чье богатство и чьи дети приносят им только убыток.","Они замыслили тяжкую хитрость","и сказали: «Не отрекайтесь от ваших богов: Вадда, Сувы, Йагуса, Йаука и Насра».","Они уже ввели в заблуждение многих. Не приумножай же беззаконникам ничего, кроме заблуждения!».","За свои грехи они были потоплены и ввергнуты в Огонь. Они не нашли себе помощников вместо Аллаха.","Нух (Ной) сказал: «Господи! Не оставь на земле ни одного неверующего жителя!","Если ты оставишь их, они введут в заблуждение Твоих рабов и породят только грешных неверующих.","Господи! Прости меня и моих родителей и тех, кто вошел в мой дом верующим, а также верующих мужчин и женщин. А беззаконникам не приумножай ничего, кроме погибели!»."],"72":["Скажи: «Мне было открыто, что несколько джиннов послушали чтение Корана и сказали: «Воистину, мы слышали удивительный Коран.","Он наставляет на прямой путь, и мы уверовали в него и не будем приобщать сотоварищей к нашему Господу.","Величие (или богатство) нашего Господа превысокое, и Он не взял Себе ни супруги, ни сына.","Глупец среди нас (Иблис) наговаривал на Аллаха чрезмерное.","Мы же думали, что ни люди, ни джинны не станут говорить об Аллахе ложь.","Мужи из числа людей искали покровительства мужей из числа джиннов, но они только увеличивали в них страх (или беззаконие).","Они думали так же, как и вы, что Аллах никого не воскресит.","Мы достигли неба, но обнаружили, что оно заполнено суровыми стражами и пылающими огнями.","Прежде мы садились там на седалищах, чтобы подслушивать. Но тот, кто подслушает сейчас, обнаружит, что его подстерегает пылающий огонь.","Мы не знаем, зло ли задумано для тех, кто на земле, или Господь пожелал направить их на прямой путь.","Среди нас есть праведные и те, которые ниже этого. Мы были разрозненными группами.","Мы знали, что не спасемся от Аллаха на земле и не спасемся от Него бегством.","Когда же мы услышали верное руководство, то уверовали в него. А тот, кто верует в своего Господа, не должен бояться ни обиды, ни притеснения.","Среди нас есть мусульмане и уклонившиеся. Те, которые стали мусульманами, последовали прямым путем.","Уклонившиеся же будут дровами для Геенны»».","Если бы они устояли на прямом пути, то Мы напоили бы их водой вволю,","чтобы этим подвергнуть их испытанию. А тех, кто отвращается от Напоминания своего Господа, Он ввергает в тяжкие мучения.","Мечети принадлежат Аллаху. Не взывайте же ни к кому наряду с Аллахом.","Когда раб Аллаха встал, обращаясь с мольбой к Нему, они столпились вокруг него (джинны столпились вокруг Пророка, чтобы послушать Коран, или неверующие ополчились против него, чтобы помешать ему).","Скажи: «Я взываю только к своему Господу и никого не приобщаю в сотоварищи к Нему».","Скажи: «Не в моей власти навредить вам или наставить вас на прямой путь».","Скажи: «Никто не защитит меня от Аллаха, и мне не найти помимо Него прибежища.","Мне остается лишь доносить истину от Аллаха и Его послания. Кто же ослушается Аллаха и Его Посланника, тому уготован огонь Геенны, в котором они пребудут вечно».","Когда же они увидят то, что им было обещано, то узнают, чьи помощники слабее и малочисленнее.","Скажи: «Я не знаю, скоро ли настанет обещанное вам, или же мой Господь отсрочил его».","Он - Ведающий сокровенное, и Он не открывает Своего сокровенного никому,","кроме тех посланников, которыми Он доволен и к которым Он приставляет спереди и сзади стражей,","чтобы знать, что они донесли послания своего Господа. Он объемлет знанием все, что с ними, и Он исчислил всякую вещь."],"73":["О закутавшийся!","Простаивай ночь без малого,","половину ночи или чуть меньше того,","или чуть больше того, и читай Коран размеренным чтением.","Мы непременно ниспошлем тебе весомые слова.","Воистину, молитвы после пробуждения среди ночи тяжелее и яснее по изложению.","Воистину, днем ты бываешь подолгу занят.","Поминай же имя Господа твоего и посвяти себя Ему полностью.","Господь востока и запада - нет божества, кроме Него. Сделай же Его своим Попечителем и Хранителем.","Терпимо относись к их словам и сторонись их красиво.","Оставь Меня с теми, кто считает истину ложью, но пользуется мирскими благами, и предоставь им небольшую отсрочку.","Воистину, есть у Нас оковы и Ад,","еда, которой давятся, и мучительные страдания.","В тот день земля и горы сотрясутся, и горы превратятся в холмы сыпучего песка.","Мы отправили к вам Посланника свидетелем против вас, подобно тому, как отправили посланника к Фараону.","Фараон ослушался посланника, и Мы схватили его Хваткой суровой.","Как же вы спасетесь, если не уверуете, в тот день, который заставит поседеть младенцев?","Небо тогда будет расколото, и обещание Его непременно исполнится.","Воистину, это - Назидание, и всякий, кто пожелает, встанет на путь к своему Господу.","Воистину, твой Господь знает, что ты и часть тех, кто с тобой, простаиваете менее двух третей ночи, или половину ее, или треть ее. Аллах определяет меру дня и ночи. Он знает, что вам не сосчитать этого, и принимает ваши покаяния. Читайте же из Корана то, что необременительно для вас. Он знает, что среди вас будут больные, что одни странствуют по земле в поисках милости Аллаха, а другие сражаются на пути Аллаха. Читайте же из него то, что необременительно для вас, совершайте намаз, раздавайте закят и одолжите Аллаху прекрасный заем. Какое бы добро вы ни приготовили для себя заранее, вы найдете его у Аллаха в виде лучшего и большего вознаграждения. Просите же у Аллаха прощения, ведь Аллах - Прощающий, Милосердный."],"74":["О завернувшийся!","Встань и увещевай!","Господа своего величай!","Одежды свои очищай!","Скверны (идолов) сторонись!","Не оказывай милости, чтобы получить большее!","Ради Господа твоего будь терпелив!","Когда же протрубят в рог,","то день тот будет Днем тяжким,","нелегким для неверующих.","Оставь Меня с тем, кого Я сотворил одиноким,","даровал ему большое богатство","и сыновей, которые находились рядом с ним,","и распростер перед ним этот мир полностью.","После всего этого он желает, чтобы Я добавил ему.","Но нет! Он упрямо отрицает Наши знамения.","Я возложу на него подъем (восхождение на гору в Аду).","Он подумал и рассчитал.","Да сгинет он! Как он рассчитал?!","Да сгинет он еще раз! Как он рассчитал?!","Затем он задумался.","Затем он нахмурился и насупился.","Затем он повернулся спиной и возгордился","и сказал: «Это - не что иное, как пересказанное колдовство.","Это - не что иное, как слова человека».","Я брошу его в Преисподнюю.","Откуда ты мог знать, что такое Преисподняя?","Она не щадит и не оставляет.","Она сжигает кожу.","Их (ангелов) над ней - девятнадцать.","Стражами Огня мы сделали только ангелов, а количество их сделали искушением для неверующих, чтобы удостоверились те, кому было даровано Писание, чтобы усилилась вера у верующих, чтобы не сомневались те, кому было даровано Писание, и верующие, и чтобы спросили те, чьи сердца поражены недугом, и неверующие: «Что хотел Аллах этой притчей?». Так Аллах вводит в заблуждение, кого пожелает, и ведет прямым путем, кого пожелает. Воинство твоего Господа не знает никто, кроме Него. Это же - не что иное, как Напоминание для человечества.","О да! Клянусь луной!","Клянусь ночью, когда она отступает!","Клянусь зарей, когда она занимается!","Это есть одно из величайших явлений,","предостерегающее человечество -","тех из вас, кто желает продвигаться вперед благодаря праведным деяниям или отступать назад, совершая грехи.","Каждый человек является заложником того, что он приобрел,","кроме людей правой стороны.","В Райских садах они будут расспрашивать друг друга","о грешниках.","Что привело вас в Преисподнюю?","Они скажут: «Мы не были в числе тех, которые совершали намаз.","Мы не кормили бедняков.","Мы погружались в словоблудие вместе с погружавшимися.","Мы считали ложью Последний день,","пока к нам не явилась убежденность (смерть)».","Заступничество заступников не поможет им.","Что же с ними? Почему они отворачиваются от Напоминания,","словно напуганные ослы,","бегущие от стрелка (или льва)?","Но ведь каждый из них желает получить развернутые свитки.","Но нет! Они не боятся Последней жизни.","Но нет! Это есть Назидание.","Помянет его тот, кто захочет.","Но они не помянут его, если этого не пожелает Аллах. Он - Тот, Кто достоин страха и способен на прощение."],"75":["Нет, клянусь Днем воскресения!","Клянусь душой попрекающей!","Неужели человек полагает, что Мы не соберем его костей?","Конечно! Мы способны восстановить даже кончики его пальцев (или сделать всего его пальцы одинаковыми, так что он не сможет пользоваться ими, как прежде).","Но человек желает и впредь совершать грехи.","Он спрашивает, когда же наступит День воскресения?","Когда взор будет ошеломлен,","луна затмится,","а солнце и луна сойдутся.","В тот день человек скажет: «Куда бежать?».","О нет! Не будет убежища!","В тот день возвращение будет к твоему Господу.","В тот день человеку возвестят о том, что он совершил заранее и что оставил после себя.","Но человек будет свидетельствовать против самого себя,","даже если он будет оправдываться.","Не шевели своим языком, повторяя его (Коран), чтобы поскорее запомнить.","Нам надлежит собрать его и прочесть.","Когда же Мы прочтем его, то читай его следом.","Нам надлежит разъяснять его.","Но нет! Вы любите жизнь ближнюю","и пренебрегаете Последней жизнью.","Одни лица в тот день будут сиять","и взирать на своего Господа.","Другие же лица в тот день будут омрачены.","Они убедятся о том, что их поразит беда.","Но нет! Когда душа достигнет ключицы,","будет сказано: «Кто же прочтет заклинание?».","Умирающий поймет, что наступило расставание.","Голень сойдется с голенью (тяготы мирской жизни объединятся с тяготами последней жизни или голени человека будут сложены вместе в саване),","и в тот день его пригонят к твоему Господу.","Он не уверовал и не совершал намаз.","Напротив, он счел это ложью и отвернулся,","а затем горделиво отправился к своей семье.","Горе тебе, горе!","Еще раз горе тебе, горе!","Неужели человек полагает, что он будет оставлен без присмотра?","Разве он не был каплей из семени источаемого?","Потом он превратился в сгусток крови, после чего Он создал его и придал ему соразмерный облик.","Он сотворил из него чету: мужчину и женщину.","Неужели Он не способен воскресить мертвых?"],"76":["Неужели не прошло то время, когда человек был безвестен?","Мы создали человека из смешанной капли, подвергая его испытанию, и сделали его слышащим и зрячим.","Мы повели его путем либо благодарным, либо неблагодарным.","Мы приготовили для неверующих цепи, оковы и пламя.","А благочестивые будут пить из чаши вино, смешанное с камфарой.","Рабы Аллаха будут пить из источника, давая ему течь полноводными ручьями.","Они исполняют обеты и боятся дня, зло которого разлетается.","Они дают пищу беднякам, сиротам и пленникам, несмотря на то, что она желанна и для них самих.","Они говорят: «Мы кормим вас лишь ради Лика Аллаха и не хотим от вас ни награды, ни благодарности!","Мы боимся от своего Господа того Мрачного и Томительного дня».","Аллах защитит их от зла того дня и одарит их процветанием и радостью.","А за то, что они проявили терпение, Он воздаст им Райскими садами и шелками.","Они будут лежать на ложах, прислонившись, и не увидят там ни солнца, ни стужи.","Тени будут близки к ним, и плоды будут подчинены им полностью.","Обходить их будут с сосудами из серебра и кубками из хрусталя -","хрусталя серебряного, соразмерных размеров.","Поить их там будут из чаш вином, смешанным с имбирем,","из источника, названного Салсабилем.","Их будут обходить вечно юные отроки. Взглянув на них, ты примешь их за рассыпанный жемчуг.","Взглянув же, ты увидишь там благодать и великую власть.","На них будут зеленые одеяния из атласа и парчи. Они будут украшены серебряными браслетами, а Господь их напоит их чистым напитком.","Таково ваше воздаяние, и ваше усердие отблагодарено.","Воистину, Мы ниспослали тебе Коран частями.","Потерпи же до решения твоего Господа и не повинуйся грешникам и неверующим среди них.","Поминай имя твоего Господа утром и перед закатом,","а также ночью. Падай ниц пред Ним и славь Его долгой ночью.","Воистину, эти любят жизнь ближнюю и оставляют позади себя Тяжкий день.","Мы создали их и укрепили их суставы. Но если Мы пожелаем, то заменим их подобными им.","Воистину, это есть Назидание, и тот, кто желает, становится на путь к своему Господу.","Но вы не пожелаете этого, если не пожелает Аллах. Воистину, Аллах - Знающий, Мудрый.","Он вводит в Свою милость, кого пожелает, а для беззаконников Он приготовил мучительные страдания."],"77":["Клянусь посылаемыми с добром,","несущимися быстро,","распространяющими бурно,","различающими твердо,","и передающими Напоминание","для оправдания или предостережения.","Обещанное вам непременно сбудется.","Когда погаснут звезды,","когда расколется небо,","когда развеются горы,","когда посланникам будет установлен срок.","До какого дня отсрочено?","До Дня различения!","Откуда ты мог знать, что такое День различения?","Горе в тот день тем, кто считает истину ложью!","Разве мы не погубили первые поколения?","Вслед за ними Мы отправили последующие поколения.","Так поступаем Мы с грешниками.","Горе в тот день тем, кто считает истину ложью!","Разве Мы не сотворили вас из презренной жидкости","и не поместили ее в надежном месте","до известного срока?","Мы предопределили меру, и как прекрасно Мы предопределяем!","Горе в тот день тем, кто считает истину ложью!","Разве Мы не сделали землю вместилищем","для живых и мертвых?","Разве Мы не воздвигли на ней незыблемые и высокие горы и не напоили вас пресной водой?","Горе в тот день тем, кто считает истину ложью!","Ступайте к тому, что вы считали ложью!","Ступайте к тени с тремя разветвлениями.","Не прохладна она и от пламени не избавляет,","а он бросает искры, подобные замку,","который выглядит словно желтые верблюды.","Горе в тот день тем, кто считает истину ложью!","В тот день они будут безмолвствовать,","и не будет им дозволено оправдываться.","Горе в тот день тем, кто считает истину ложью!","Вот День различения! Мы собрали вас и тех, кто был прежде.","Если у вас есть какая-нибудь хитрость, то ухитритесь против Меня!","Горе в тот день тем, кто считает истину ложью!","А богобоязненные, воистину, пребудут среди сеней и источников","и плодов, каких только пожелают.","Ешьте и пейте во здравие за то, что вы совершали!","Так Мы вознаграждаем творящих добро.","Горе в тот день тем, кто считает истину ложью!","Вкушайте и наслаждайтесь недолго, ведь вы являетесь грешниками.","Горе в тот день тем, кто считает истину ложью!","Когда им говорят: «Поклонитесь!». - они не кланяются.","Горе в тот день тем, кто считает истину ложью!","В какой же рассказ после этого вы уверуете?"],"78":["О чем они расспрашивают друг друга?","О великой вести,","относительно которой они расходятся во мнениях.","Но нет, они узнают!","Еще раз нет, они узнают!","Разве Мы не сделали землю ложем,","а горы - колышками?","Мы сотворили вас парами,","и сделали ваш сон отдыхом,","и сделали ночь покрывалом,","и сделали день жалованием,","и воздвигли над вами семь твердынь,","и установили пылающий светильник,","и низвели из облаков обильно льющуюся воду,","чтобы взрастить ею зерна и растения","и густые сады.","Воистину, День различения назначен на определенное время.","В тот день затрубят в Рог, и вы придете толпами,","и небо раскроется и станет вратами,","и горы придут в движение и станут маревом.","Воистину, Геенна является засадой","и местом возвращения для тех, кто преступает границы дозволенного.","Они пробудут там долгие годы,","не вкушая ни прохлады, ни питья,","а только кипяток и гной.","Это будет подобающим возмездием.","Воистину, они не надеялись на расчет","и полностью отрицали Наши знамения.","Мы же всякую вещь подсчитали и записали.","Вкушайте же! Мы не прибавим вам ничего, кроме мучений.","Воистину, богобоязненных ожидает место спасения,","Райские сады и виноградники,","и полногрудые сверстницы,","и полные чаши.","Они не услышат там ни пустословия, ни лжи.","Это будет воздаянием от твоего Господа и даром исчисленным (или щедрым, или достаточным),","Господа небес и земли и того, что между ними, Милостивого, с Которым они не посмеют даже заговорить.","В тот день, когда Дух (Джибрил) и ангелы станут рядами, не будет говорить никто, кроме тех, кому позволит Милостивый, и говорить они будут правду.","Это будет истинный день, и всякий, кто пожелает, найдет способ вернуться к своему Господу.","Мы предостерегли вас от наказания близкого. В тот день человек увидит, что уготовили его руки, а неверующий скажет: «Эх, если бы я был прахом!»."],"79":["Клянусь исторгающими души неверующих жестоко!","Клянусь извлекающими души верующих нежно!","Клянусь плывущими стремительно,","опережающими уверенно","и исполняющими повеления!","В тот день сотрясется сотрясающаяся (раздастся первый трубный глас, после которого творения умрут),","вслед за чем последует еще одно сотрясение (раздастся второй трубный глас, после которого начнется воскрешение),","В тот день затрепещут сердца,","а их взоры будут смиренны.","Они говорят: «Неужели мы вернемся в прежнее состояние","после того, как станем истлевшими костями?!».","Они говорят: «Если так, то это - невыгодное возвращение!».","Но раздастся лишь один глас,","и все они окажутся на поверхности земли.","Дошел ли до тебя рассказ о Мусе (Моисее)?","Вот Господь его воззвал к нему в священной долине Тува (Това):","«Ступай к Фараону, ибо он преступил границы дозволенного,","и скажи: «Не следует ли тебе очиститься?","Я укажу тебе путь к твоему Господу, и ты станешь богобоязнен»».","Он показал ему величайшее знамение,","но тот счел его ложью и ослушался,","а потом отвернулся, принявшись усердствовать.","Он собрал толпу и громко воззвал,","и сказал: «Я - ваш всевышний господь!».","Тогда Аллах подверг его наказанию как в Последней жизни, так и в первой жизни.","Воистину, в этом было назидание для тех, кто богобоязнен.","Вас ли труднее создать или небо? Он воздвиг его,","поднял его своды и сделал его совершенным.","Он сделал темной ночь его (неба) и вывел его утреннюю зарю.","После этого Он распростер землю,","вывел из нее воду и пастбища","и утвердил на ней горы","на пользу вам и вашему скоту.","Когда же наступит Величайшее бедствие (День воскресения),","в тот день человек вспомнит о том, в чем он усердствовал,","и Ад будет ясно виден тем, кто будет видеть.","Тому, кто преступил границы дозволенного","и отдал предпочтение мирской жизни,","пристанищем будет Ад.","Тому же, кто боялся предстать перед своим Господом и удерживал себя от страстей,","пристанищем будет Рай.","Тебя спрашивают о Часе: «Когда же он настанет?».","К чему тебе упоминать об этом?","Только твой Господь ведает об этом.","Воистину, ты - всего лишь предостерегающий увещеватель для тех, кто опасается этого.","В тот день, когда они увидят его, им покажется, что они провели в этом мире лишь послеполуденные часы или утро."],"80":["Он нахмурился и отвернулся,","потому что к нему подошел слепой.","Откуда тебе знать? Возможно, он бы очистился","или помянул бы наставление, и поминание принесло бы ему пользу.","Тому, кто решил, что он ни в чем не нуждается,","ты уделяешь внимание,","Что же будет тебе, если он не очистится?","А того, кто приходит к тебе со рвением","и страшится Аллаха,","ты оставляешь без внимания.","Но нет! Это есть Назидание,","и пусть помянет его всякий желающий.","Оно записано в свитках почитаемых,","вознесенных и очищенных,","в руках посланцев","благородных и покорных.","Да сгинет человек! Как же он неблагодарен!","Из чего Он сотворил его?","Он сотворил его из капли и соразмерил (или предопределил стадии его развития),","потом облегчил ему путь,","потом умертвил его и поместил в могилу.","Потом, когда пожелает, Он воскресит его.","Но нет! Он не выполняет того, что Он приказал ему.","Пусть посмотрит человек на свое пропитание!","Мы проливаем обильные ливни,","затем рассекаем землю трещинами","и взращиваем на ней зерна,","виноград и люцерну,","маслины и финиковые пальмы,","сады густые (или с могучими деревьями),","фрукты и травы","на пользу вам и вашей скотине.","Когда же раздастся Оглушительный глас,","в тот день человек бросит своего брата,","свою мать и своего отца,","свою жену и своих сыновей,","ибо у каждого человека своих забот будет сполна.","В тот день одни лица будут сиять,","смеяться и ликовать.","На других же лицах в тот день будет прах,","покрывающий их мраком.","Это будут неверующие грешники."],"81":["Когда солнце будет свернуто (или потеряет свое сияние, или будет выброшено),","когда падут звезды,","когда горы будут сдвинуты с мест (или приведены в движение),","когда верблюдицы на десятом месяце беременности останутся без присмотра,","когда дикие звери будут собраны,","когда моря запылают (или переполнятся; или опустеют; или перемешаются; или станут красными),","когда души объединятся (праведники объединятся с праведниками, а грешники - с грешниками; или праведники соединятся с райскими гуриями, а неверующие - с дьяволами; или души соединятся с телами),","когда зарытую живьем спросят,","за какой грех ее убили,","когда свитки с деяниями рабов будут развернуты,","когда небо будет сдернуто,","когда Ад будет разожжен с новой силой,","когда Рай будет приближен к праведникам,","тогда познает душа, что она принесла.","Но нет! Клянусь телами небесными - отступающими,","передвигающимися и исчезающими!","Клянусь ночью, когда она наступила (или отступила)!","Клянусь рассветом, когда он забрезжил!","Это - слова благородного посланца,","обладателя силы при Владыке Трона, почитаемого,","которому там (на небесах) повинуются, доверенного.","Ваш товарищ (Мухаммад) не является одержимым.","Он видел его (Джибрила) на ясном горизонте","и не скупится передать сокровенное.","Это - не речи дьявола изгнанного, побиваемого.","Куда же вы направляетесь?","Это - лишь Напоминание мирам,","тем из вас, кто желает следовать прямым путем.","Но вы не пожелаете этого, если этого не пожелает Аллах, Господь миров."],"82":["Когда небо расколется,","когда тела небесные осыплются,","когда моря перельются и смешаются (или высохнут),","когда могилы перевернутся,","тогда каждая душа узнает, что она совершила и что оставила после себя.","О человек! Что ввело тебя в заблуждение относительно твоего Великодушного Господа,","Который сотворил тебя и сделал твой облик совершенным и соразмеренным?","Он сложил тебя в том облике, в каком пожелал.","Но нет! Вы же считаете ложью воздаяние.","Воистину, над вами есть хранители -","благородные писцы,","которые знают о том, что вы совершаете.","Воистину, благочестивые окажутся в блаженстве.","Воистину, грешники окажутся в Аду,","куда они войдут в День воздаяния.","Они не смогут избежать этого.","Откуда ты мог знать, что такое День воздаяния?","Да, откуда ты мог знать, что такое День воздаяния?","В тот день ни одна душа не сможет ничем помочь другой, и власть в тот день будет принадлежать Аллаху."],"83":["Горе обвешивающим,","которые требуют дать им сполна, когда люди отмеривают им,","а когда сами мерят или взвешивают для других, то наносят им урон.","Разве не думают они, что будут воскрешены","в Великий день -","в тот день, когда люди предстанут перед Господом миров?","Но нет! Книга грешников находится в Сиджжине.","Откуда ты мог знать, что такое Сиджжин?","Это - книга начертанная, в которой записаны все злодеяния дьяволов, неверующих и грешников (или скала под седьмой землей, под которой находится начертанная книга с деяниями грешников).","Горе в тот день тем, кто считает истину ложью,","кто считает ложью День воздаяния!","Его считает ложью только преступник и грешник.","Когда ему читают Наши аяты, он говорит: «Это - легенды древних народов!».","Но нет! Напротив, их сердца окутаны тем, что они приобрели.","Но нет! В тот день они будут отделены от своего Господа завесой (не увидят Аллаха),","а потом они попадут в Ад,","после чего им скажут: «Вот то, что вы считали ложью».","Но нет! Книга благочестивых окажется в Иллийюне.","Откуда ты мог знать, что такое Иллийюн?","Это - книга начертанная, в которой записаны все добрые деяния праведников (или верховья Рая, где находится начертанная книга с деяниями праведников).","Ее видят (или о ней будут свидетельствовать) приближенные.","Воистину, благочестивые окажутся в блаженстве","и будут на ложах созерцать райские блага.","На их лицах ты увидишь блеск благоденствия.","Их будут поить выдержанным запечатанным вином,","а печатью его будет мускус (оно запечатано мускусом или же последний глоток его будет иметь привкус мускуса). Пусть же ради этого состязаются состязающиеся!","Оно смешано с напитком из Таснима -","источника, из которого пьют приближенные.","Грешники смеялись над теми, которые уверовали.","Проходя мимо них, они подмигивали друг другу,","возвращаясь к своим семьям, они возвращались радостными (или),","а при виде их они говорили: «Воистину, эти впали в заблуждение».","А ведь они не были посланы к ним хранителями.","В тот день верующие будут смеяться над неверующими","и на ложах созерцать райские блага и то ужасное положение, в котором окажутся грешники.","Разве неверующие не получат воздаяние за то, что они совершали?"],"84":["Когда небо разверзнется","и внемлет своему Господу, как ему надлежит,","когда земля будет распростерта,","извергнет то, что в ней, и опустеет,","и внемлет своему Господу, как ей надлежит...","О человек! Ты стремишься к своему Господу и встретишься с Ним.","Тот, кому его книга будет вручена в правую руку,","получит легкий расчет","и вернется к своей семье радостным.","А тот, кому его книга будет вручена из-за спины,","станет призывать погибель","и войдет в Пламень.","Он радовался, находясь в кругу своей семьи,","и полагал, что не вернется обратно.","Но нет! Господь его видел его.","Но нет! Клянусь вечерней зарею!","Клянусь ночью и тем, что она собирает!","Клянусь луной в полнолуние!","Вы переходите из одного состояния в другое.","Почему же они не веруют","и не падают ниц, когда им читают Коран?","Но неверующие считают это ложью,","Аллаху же лучше знать, что они хранят (какие добрые и злые деяния они совершают).","Обрадуй же их мучительными страданиями,","кроме тех, которые уверовали и совершали праведные деяния. Им уготована награда неиссякаемая."],"85":["Клянусь небом с созвездиями Зодиака!","Клянусь днем обещанным!","Клянусь свидетельствующим и засвидетельствованным!","Да сгинут собравшиеся у рва -","огненного, поддерживаемого растопкой!","Вот они уселись возле него,","будучи свидетелями того, что творят с верующими.","Они вымещали им только за то, что те уверовали в Аллаха Могущественного, Достохвального,","Которому принадлежит власть над небесами и землей. Аллах же - Свидетель всякой вещи!","Тем, которые подвергли искушению (или сожгли в огне) верующих мужчин и женщин и не раскаялись, уготованы мучения в Геенне, мучения от обжигающего Огня.","Тем же, которые уверовали и совершали праведные деяния, уготованы Райские сады, в которых текут реки. Это - великое преуспеяние!","Воистину, Хватка твоего Господа сурова!","Воистину, Он начинает и повторяет (создает творение в первый раз и воссоздает его или начинает наказывать в этом мире и возобновляет наказание в Последней жизни).","Он - Прощающий, Любящий (или Любимый),","Владыка Трона, Славный (или Владыка Трона славного).","Он вершит то, что пожелает.","Дошел ли до тебя рассказ о воинствах,","о Фараоне и самудянах?","Но неверующие считают это ложью,","Аллах же окружает их сзади.","Да, это - славный Коран","в Хранимой скрижали."],"86":["Клянусь небом и ночным путником!","Откуда ты мог знать, что такое ночной путник?","Это - звезда пронизывающая небеса своим светом.","Нет души, при которой не было бы хранителя.","Пусть посмотрит человек, из чего он создан.","Он создан из изливающейся жидкости,","которая выходит между чреслами и грудными костями.","Воистину, Он способен вернуть его.","В тот день будут испытаны (или раскроются) тайны,","и тогда не будет у него ни силы, ни помощника.","Клянусь небом возвращающим (возвращающим воду земле или возвращающим небесные тела, которые восходят с одной стороны и заходят в другой)!","Клянусь землей раскалываемой (при прорастании растений, или при выходе из земли воды, или при воскрешении мертвых)!","Воистину, это - Слово различающее,","а не шутка.","Они замышляют козни,","и Я замышляю козни.","Предоставь же неверующим отсрочку, помедли с ними недолго!"],"87":["Славь имя Господа твоего Всевышнего,","Который сотворил все сущее и всему придал соразмерность,","Который предопределил судьбу творений и указал путь,","Который взрастил пастбища,","а потом превратил их в темный сор.","Мы позволим тебе прочесть Коран, и ты не забудешь ничего,","кроме того, что пожелает Аллах. Он знает явное и то, что сокрыто.","Мы облегчим тебе путь к легчайшему.","Наставляй же людей, если напоминание принесет пользу.","Воспримет его тот, кто страшится,","и уклонится от него самый несчастный,","который войдет в Огонь величайший.","Не умрет он там и не будет жить.","Преуспел тот, кто очистился,","поминал имя своего Господа и совершал намаз.","Но нет! Вы отдаете предпочтение мирской жизни,","хотя Последняя жизнь - лучше и дольше.","Воистину, это записано в первых свитках -","свитках Ибрахима (Авраама) и Мусы (Моисея)."],"88":["Дошел ли до тебя рассказ о Покрывающем (Дне воскресения)?","Одни лица в тот день будут унижены,","изнурены и утомлены.","Они войдут в Огонь жаркий.","Их будут поить из источника кипящего","и кормить только ядовитыми колючками,","от которых не поправляются и которые не утоляют голода.","Другие же лица в тот день будут радостны.","Они будут довольны своими стараниями","в Вышних садах.","Они не услышат там словоблудия.","Там есть источник текущий.","Там воздвигнуты ложа,","расставлены чаши,","разложены подушки,","и разостланы ковры.","Неужели они не видят, как созданы верблюды,","как вознесено небо,","как водружены горы,","как распростерта земля?","Наставляй же, ведь ты - наставник,","и ты не властен над ними.","А тех, кто отвернется и не уверует,","Аллах подвергнет величайшим мучениям.","К Нам они вернутся,","и затем Мы потребуем у них отчета."],"89":["Клянусь зарею!","Клянусь десятью ночами!","Клянусь четом и нечетом!","Клянусь ночью, когда она проходит!","Неужели этих клятв не достаточно для обладающего разумом?","Неужели ты не видел, как Господь твой поступил с адитами -","народом Ирама, обладавшим колоннами (воздвигавшим высокие здания с колоннами или обладавшим могучим сложением и огромной силой),","подобных которому не было сотворено в городах?","С самудянами, рассекавшими скалы в лощине?","С Фараоном, владевшим кольями (обладавшим множеством воинов, которые поддерживали его власть, подобно тому, как колышки поддерживают шатер, или привязывавшим людей к кольям во время казни)?","Они преступали границы дозволенного на земле","и распространяли в них много нечестия.","Тогда твой Господь пролил на них бич мучений.","Воистину, твой Господь - в засаде (предоставляет отсрочку грешникам, чтобы затем неожиданно наказать их за ослушание).","Когда Господь испытывает человека, оказывая ему милость и одаряя его благами, тот говорит: «Господь мой почтил меня!».","Когда же Он испытывает его, ограничивая его в пропитании, тот говорит: «Господь мой унизил меня!».","Но нет! Вы же сами не почитаете сироту,","не побуждаете друг друга кормить бедняка,","жадно (или целиком) пожираете наследство","и страстно любите богатство.","Но нет! Когда земля разобьется и превратится в песок.","и твой Господь придет с ангелами, выстроившимися рядами,","в тот день приведут Геенну, и тогда человек помянет назидание. Но к чему такое поминание?","Он скажет: «Эх, если бы я заранее позаботился о своей жизни!».","В тот день никто не причинит таких мучений, как Он,","и никто не наложит таких оков, как Он.","О обретшая покой душа!","Вернись к своему Господу удовлетворенной и снискавшей довольство!","Войди в круг Моих рабов!","Войди в Мой Рай!"],"90":["Нет, клянусь этим городом (Меккой)!","Ты обитаешь в этом городе (или Тебе будет дозволено сражаться в этом городе).","Клянусь родителем и тем, кого он породил (Адамом и его потомством, или Ибрахимом и его потомками, в том числе Исмаилом и Мухаммадом)!","Мы создали человека в тяготах.","Неужели он полагает, что никто не справится с ним?","Он говорит: «Я погубил богатство несметное!».","Неужели он полагает, что никто не видел его?","Разве Мы не наделили его двумя глазами,","языком и двумя устами?","Разве Мы не указали ему на две восходящие тропы?","Но он не стал преодолевать крутую тропу.","Откуда ты мог знать, что такое крутая тропа?","Это - освобождение раба","или кормление в голодный день","сироту из числа родственников","или приникшего к земле бедняка.","А после этого надо быть одним из тех, которые уверовали и заповедали друг другу терпение и заповедали друг другу милосердие.","Таковы люди правой стороны.","Те же, которые не уверовали в Наши знамения, являются людьми левой стороны,","над которыми сомкнется Огонь."],"91":["Клянусь солнцем и его утренним сиянием!","Клянусь луной, когда она следует за ним!","Клянусь днем, когда он делает его (солнце) ясным!","Клянусь ночью, когда она скрывает его (солнце)!","Клянусь небом и Тем, Кто его воздвиг (или тем, как Он воздвиг его)!","Клянусь землей и Тем, Кто ее распростер (или тем, как Он распростер ее)!","Клянусь душой и Тем, Кто придал ей совершенный облик (или тем, как Он сделал ее облик совершенным)","и внушил ей порочность ее и богобоязненность!","Преуспел тот, кто очистил ее,","и понес урон тот, кто скрыл ее (опорочил, облек в несправедливость).","Самудяне сочли лжецом пророка Салиха из-за своего беззакония,","и тогда самый несчастный из них вызвался убить верблюдицу.","Посланник Аллаха (Салих) сказал им: «Берегите верблюдицу и питье ее!».","Они сочли его лжецом и подрезали ей поджилки, и за этот грех Господь их подверг их наказанию, которое было одинаковым для всех (или сровнял над ними землю).","И не опасался Он последствий этого."],"92":["Клянусь ночью, когда она покрывает землю!","Клянусь днем, когда он проясняется!","Клянусь Тем, Кто создал мужчину и женщину!","Ваши стремления различны.","Тому, кто отдавал должное (или раздавал милостыню) и был богобоязнен,","кто признавал наилучшее (свидетельство единобожия или Рай),","Мы облегчим путь к легчайшему (к праведным деяниям).","А тому, кто был скуп и полагал, что ни в чем не нуждается,","кто счел ложью наилучшее (свидетельство единобожия или Рай),","Мы облегчим путь к тягчайшему (к злу и наказанию).","Не спасет его достояние, когда он падет (в Геенну или погибнет).","Воистину, Нам надлежит вести прямым путем.","Нам же принадлежат жизнь Последняя и первая.","Я предостерег вас от пылающего Огня.","Войдет в него только самый несчастный,","который считает истину ложью и отворачивается.","Отдален от него будет самый богобоязненный,","который раздает свое имущество, очищаясь,","и всякую милость возмещает сполна","только из стремления к Лику своего Всевышнего Господа.","И он непременно будет удовлетворен."],"93":["Клянусь утром!","Клянусь ночью, когда она успокаивается (или покрывается мраком)!","Не покинул тебя твой Господь и не возненавидел.","Воистину, будущее для тебя лучше, чем настоящее.","Господь твой непременно одарит тебя, и ты будешь удовлетворен.","Разве Он не нашел тебя сиротой и не дал тебе приют?","Он нашел тебя заблудшим и повел прямым путем.","Он нашел тебя бедным и обогатил.","Посему не притесняй сироту!","И не гони просящего!","И возвещай о милости своего Господа."],"94":["Разве Мы не раскрыли для тебя грудь твою?","и не сняли с тебя ношу,","которая отягощала твою спину?","Разве Мы не возвеличили для тебя славу твою?","Воистину, за каждой тягостью наступает облегчение.","За каждой тягостью наступает облегчение.","Посему, как только освободишься, будь деятелен (как только освободишься от мирских дел, усердно поклоняйся Аллаху, или как только завершишь намаз, усердно взывай к Аллаху с молитвами)","и устремись к своему Господу."],"95":["Клянусь смоковницей и оливой!","Клянусь горой Синин (Синай)!","Клянусь этим безопасным городом (Меккой)!","Мы сотворили человека в прекраснейшем облике.","Потом Мы вернем его в нижайшее из низких (продлим ему жизнь настолько, что он превратится в дряхлого старика, или бросим его на самое дно Геенны),","за исключением тех, которые уверовали и совершали праведные деяния. Им уготована награда неиссякаемая.","Что же после этого заставляет тебя считать ложью воздаяние?","Разве Аллах не является Наимудрейшим Судьей?"],"96":["Читай во имя твоего Господа, Который сотворил все сущее,","сотворил человека из сгустка крови.","Читай, ведь твой Господь - Самый великодушный.","Он научил посредством письменной трости -","научил человека тому, чего тот не знал.","Но нет! Человек преступает границы дозволенного,","когда ему кажется, что он ни в чем не нуждается.","Но к твоему Господу предстоит возвращение.","Что ты думаешь о том, кто мешает","рабу, когда тот молится?","Что ты думаешь, а если он был на правом пути","или призывал к богобоязненности?","Что ты думаешь, а если он счел ложью истину и отвернулся?","Неужели он не знал, что Аллах видит его?","Но нет, если он не перестанет, то Мы схватим его за хохол -","хохол лживый, грешный.","Пусть он зовет свое сборище.","Мы же позовем адских стражей!","Так нет! Не повинуйся ему, а пади ниц и приближайся к Аллаху."],"97":["Воистину, Мы ниспослали его (Коран) в ночь предопределения (или величия).","Откуда ты мог знать, что такое ночь предопределения (или величия)?","Ночь предопределения (или величия) лучше тысячи месяцев.","В эту ночь ангелы и Дух (Джибрил) нисходят с дозволения их Господа по всем Его повелениям.","Она благополучна вплоть до наступления зари."],"98":["Неверующие из людей Писания и многобожников не расстались с неверием, пока к ним не явилось ясное знамение -","Посланник от Аллаха, который читает очищенные свитки.","В них содержатся правдивые Писания.","Те, кому было даровано Писание, распались только после того, как к ним явилось ясное знамение.","А ведь им было велено лишь поклоняться Аллаху, служа ему искренне, как ханифы, совершать намаз и выплачивать закят. Это - правая вера.","Воистину, неверующие из людей Писания и многобожников окажутся в огне Геенны и пребудут там вечно. Они являются наихудшими из тварей.","Воистину, те, которые уверовали и совершали праведные деяния, являются наилучшими из тварей.","Их воздаянием у их Господа будут сады Эдема, в которых текут реки. Они пребудут в них вечно. Аллах доволен ими, и они довольны Им. Это уготовано для тех, кто боится своего Господа."],"99":["Когда земля содрогнется от сотрясений,","когда земля извергнет свою ношу,","и человек спросит, что же с нею,","в тот день она расскажет свои известия,","потому что Господь твой внушит ей это.","В тот день люди выйдут толпами, чтобы им показали их деяния.","Тот, кто сделал добро весом в мельчайшую частицу, увидит его.","И тот, кто сделал зло весом в мельчайшую частицу, увидит его."],"100":["Клянусь скачущими, запыхаясь!","Клянусь высекающими искры копытами!","Клянусь нападающими на заре!","Тем самым они поднимают столб пыли","и врываются с ним (со столбом пыли или с всадником) в гущу.","Воистину, человек неблагодарен своему Господу,","и он сам является тому свидетелем.","Воистину, он страстно любит блага.","Неужели он не знает, что, когда будет опрокинуто то, что в могилах,","и когда обнаружится то, что в груди,","в тот день Господь их будет осведомлен о них?"],"101":["Великое бедствие (День воскресения)!","Что такое Великое бедствие (День воскресения)?","Откуда ты мог знать, что такое Великое бедствие (День воскресения)?","В тот день люди будут подобны рассеянным мотылькам,","а горы будут подобны расчесанной шерсти.","Тогда тот, чья чаша Весов окажется тяжелой,","обретет приятную жизнь.","Для того же, чья чаша Весов окажется легкой,","матерью станет Пропасть (грешники будут искать убежище в Аду, подобно тому, как ребенок ищет убежище у своей матери; или грешники будут падать в Адскую Пропасть вниз головой).","Откуда ты мог знать, что это такое?","Это - жаркий Огонь!"],"102":["Страсть к приумножению (похвальба богатством и детьми) увлекает вас","настолько, что вы посещаете кладбища, чтобы бахвалиться своими покойниками (или пока вы сами не посетите могилы).","Но нет! Скоро вы узнаете!","Еще раз нет! Скоро вы узнаете!","Но нет! Если бы вы только обладали убедительным знанием!","А ведь вы непременно увидите Ад.","Вы увидите его глазами убежденными.","В тот день вы будете спрошены о благах."],"103":["Клянусь предвечерним временем (или временем)!","Воистину, каждый человек в убытке,","кроме тех, которые уверовали, совершали праведные деяния, заповедали друг другу истину и заповедали друг другу терпение!"],"104":["Горе всякому хулителю и обидчику,","который копит состояние и пересчитывает его,","думая, что богатство увековечит его.","Но нет! Его непременно ввергнут в Огонь сокрушающий.","Откуда ты мог знать, что такое Огонь сокрушающий?","Это - разожженный Огонь Аллаха,","который вздымается над сердцами.","Воистину, он сомкнется над ними","высокими столбами (мученики будут прикованы к этим столбам или врата Ада будут заперты и закреплены этими столбами)."],"105":["Разве ты не видел, что сделал твой Господь с владельцами слона?","Разве Он не запутал их козни","и не наслал на них птиц стаями?","Они бросали в них каменья из обожженной глины","и превратили их в подобие изъеденных иссохших злаковых листьев."],"106":["Ради единения курейшитов,","единения их во время зимних и летних поездок.","Пусть же они поклоняются Господу этого Дома (Каабы),","Который накормил их после голода и избавил их от страха."],"107":["Видел ли ты того, кто считает ложью воздаяние?","Это - тот, кто гонит сироту","и не побуждает накормить бедняка.","Горе молящимся,","которые небрежны к своим намазам,","которые лицемерят","и отказывают даже в мелочи!"],"108":["Мы даровали тебе аль-Каусар (бесчисленные блага, в том числе одноименную реку в Раю).","Посему совершай намаз ради своего Господа и закалывай жертву.","Воистину, твой ненавистник сам окажется безвестным."],"109":["Скажи: «О неверующие!","Я не поклоняюсь тому, чему поклоняетесь вы,","а вы не поклоняетесь Тому, Кому поклоняюсь я.","Я не поклоняюсь так, как поклоняетесь вы (или тому, чему поклоняетесь вы),","а вы не поклоняетесь так, как поклоняюсь я (или Тому, Кому поклоняюсь я).","У вас есть ваша религия, а у меня - моя!»."],"110":["Когда придет помощь Аллаха и настанет победа,","когда ты увидишь, как люди толпами обращаются в религию Аллаха,","восславь же хвалой Господа своего и попроси у Него прощения. Воистину, Он - Принимающий покаяния."],"111":["Да пропадут пропадом руки Абу Лахаба, и сам он пропал.","Не спасло его богатство и то, что он приобрел (положение в обществе и дети).","Он попадет в пламенный Огонь.","Жена его будет носить дрова,","а на шее у нее будет плетеная веревка из пальмовых волокон."],"112":["Скажи: «Он - Аллах Единый,","Аллах Самодостаточный.","Он не родил и не был рожден,","и нет никого равного Ему»."],"113":["Скажи: «Прибегаю к защите Господа рассвета","от зла того, что Он сотворил,","от зла мрака, когда он наступает,","от зла колдуний, поплевывающих на узлы,","от зла завистника, когда он завидует»."],"114":["Скажи: «Прибегаю к защите Господа людей,","Царя людей,","Бога людей,","от зла искусителя отступающего (или сжимающегося) при поминании Аллаха,","который наущает в груди людей","и бывает из джиннов и людей»."]};
